INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('a0f5eae1-7316-50ca-adf7-cc30fb209b9a', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 7, 7, 'Which statement is Charles''s law?', NULL, 1, 'multiple_choice'::answer_type, 'For a fixed mass of gas at constant pressure, the volume is directly proportional to the thermodynamic temperature', NULL, false, NULL, false, NULL, 'V ∝ T at constant p, with T in kelvin. Proportionality fails with Celsius temperatures because 0 °C is not the zero of volume. Mark scheme (1 mark). B1: C (For a fixed mass of gas at constant pressure, the volume is directly proportional to the thermodynamic temperature).', 1),
('57ecc9b3-123d-5b4c-8f99-c584cbef31db', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 8, 8, 'A patient''s body temperature is 37 °C. Convert this to a thermodynamic temperature in kelvin.', NULL, 1, 'numeric'::answer_type, '310', 'K', false, NULL, false, NULL, 'T = 37 + 273 = 310 K. Mark scheme (1 mark). A1: T = 310 K.', 1),
('948f03ec-b361-5e6c-a609-378b5a17cbef', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 9, 9, 'Liquid nitrogen boils at 77 K. Express this temperature in degrees Celsius.', NULL, 1, 'numeric'::answer_type, '-196', '°C', false, NULL, true, NULL, 'θ = 77 − 273 = −196 °C. Mark scheme (1 mark). A1: θ = −196 °C.', 1),
('72689b39-2b43-5618-9f7f-c67829fb8261', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 10, 10, 'What is meant by the absolute zero of temperature?', NULL, 1, 'multiple_choice'::answer_type, 'The temperature at which an ideal gas would exert no pressure, because its molecules would have minimum (zero) kinetic energy', NULL, false, NULL, false, NULL, 'Absolute zero, 0 K or −273 °C, is where the extrapolated pressure (or volume) of an ideal gas falls to zero. Mark scheme (1 mark). B1: A (The temperature at which an ideal gas would exert no pressure, because its molecules would have minimum (zero) kinetic energy).', 1),
('5a7a3c02-0c02-5c19-867a-dba1262ba1f1', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 11, 11, 'A balloon has a volume of 3.0 litres in a room at 20 °C. It is placed in a freezer at −18 °C, and its pressure stays the same. Calculate its new volume in litres.', NULL, 1, 'numeric'::answer_type, '2.611', 'litres', false, NULL, false, NULL, 'T₁ = 20 + 273 = 293 K and T₂ = −18 + 273 = 255 K. V₂ = V₁T₂/T₁ = 3.0 × 255 ÷ 293 = 2.61 litres. Mark scheme (2 marks). C1: both temperatures in kelvin. A1: V = 2.61 litres.', 2),
('94555e4b-eb93-5768-95ee-49bca75725a3', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 12, 12, 'A car tyre contains air at an absolute pressure of 2.2 × 10⁵ Pa at 10 °C. After a long drive the air is at 40 °C. Assuming the volume is constant, calculate the new pressure.', NULL, 1, 'numeric'::answer_type, '2.433e5', 'Pa', false, NULL, false, NULL, 'p₂ = p₁T₂/T₁ = 2.2 × 10⁵ × 313 ÷ 283 = 2.43 × 10⁵ Pa. Mark scheme (2 marks). C1: p/T constant with T in kelvin. A1: p = 2.43 × 10⁵ Pa.', 2),
('bbdcc5be-6581-5548-9e6c-a802d2aa9664', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 13, 13, 'The volume of a fixed mass of gas at constant pressure is plotted against its temperature in °C. The straight line is extended back to zero volume. Where does it meet the temperature axis?', NULL, 1, 'multiple_choice'::answer_type, 'At about −273 °C', NULL, false, NULL, false, NULL, 'Extrapolating V against θ always reaches V = 0 at about −273 °C: absolute zero. Mark scheme (1 mark). B1: D (At about −273 °C).', 1),
('366bfc27-c22e-5d1d-a2ae-6fdaa55117da', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 14, 14, 'For a fixed mass of gas at constant pressure, which graph is a straight line through the origin?', NULL, 1, 'multiple_choice'::answer_type, 'Volume against thermodynamic temperature in kelvin', NULL, false, NULL, false, NULL, 'V ∝ T only when T is measured from absolute zero. Mark scheme (1 mark). B1: B (Volume against thermodynamic temperature in kelvin).', 1),
('6c9ece2d-2d06-5a13-90b8-69cfa9f55bdd', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 15, 15, 'A sealed rigid flask of air is at 1.5 × 10⁵ Pa and 300 K. It is heated until the pressure reaches 2.4 × 10⁵ Pa. Calculate the new temperature of the air.', NULL, 1, 'numeric'::answer_type, '480', 'K', false, NULL, false, NULL, 'T₂ = T₁p₂/p₁ = 300 × 2.4 × 10⁵ ÷ 1.5 × 10⁵ = 480 K. Mark scheme (2 marks). C1: p ∝ T at constant volume. A1: T = 480 K.', 2),
('926f5660-3c06-551d-b1d6-5275302ddeb5', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 16, 16, 'A gas at constant pressure is warmed from 20 °C to 40 °C. Why does its volume not double?', NULL, 1, 'multiple_choice'::answer_type, 'Its thermodynamic temperature only rises from 293 K to 313 K', NULL, false, NULL, false, NULL, 'Doubling the Celsius value is not doubling the kelvin temperature: V increases by the factor 313/293, about 7 %. Mark scheme (1 mark). B1: C (Its thermodynamic temperature only rises from 293 K to 313 K).', 1),
('8c77281b-eca4-5c71-8a31-a68db6b99ffd', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 17, 17, 'A sample of 2500 m³ of air at 290 K is heated at constant pressure to 360 K. Calculate its new volume.', NULL, 1, 'numeric'::answer_type, '3103', 'm³', false, NULL, false, NULL, 'V₂ = V₁T₂/T₁ = 2500 × 360 ÷ 290 = 3100 m³. Mark scheme (2 marks). C1: V/T constant. A1: V = 3100 m³.', 2),
('aa65b2d5-e065-5dcd-96c8-e1f9487f01c2', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 18, 18, 'For a fixed mass of gas held at constant volume, which pair of quantities is directly proportional?', NULL, 1, 'multiple_choice'::answer_type, 'Pressure and thermodynamic temperature', NULL, false, NULL, false, NULL, 'This is the pressure law: p ∝ T at constant V, with T in kelvin. Mark scheme (1 mark). B1: A (Pressure and thermodynamic temperature).', 1),
('3d0614a6-e522-59b2-b33c-574592a8f2bd', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 19, 19, 'An aerosol can contains gas at 3.0 × 10⁵ Pa at 20 °C. It is thrown onto a fire and heated to 400 °C. Calculate the pressure of the gas, assuming the can does not expand.', NULL, 1, 'numeric'::answer_type, '6.891e5', 'Pa', false, NULL, false, NULL, 'T₁ = 293 K and T₂ = 673 K. p₂ = 3.0 × 10⁵ × 673 ÷ 293 = 6.89 × 10⁵ Pa. Mark scheme (2 marks). C1: temperatures in kelvin. A1: p = 6.89 × 10⁵ Pa.', 2),
('4f2d8e19-6f12-5902-8544-b819fe97af7d', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 20, 20, 'Why are aerosol cans labelled "Do not expose to temperatures above 50 °C"?', NULL, 1, 'multiple_choice'::answer_type, 'At constant volume the gas pressure rises with temperature and could burst the can', NULL, false, NULL, false, NULL, 'With V fixed, p ∝ T: a large temperature rise can raise the pressure beyond what the can withstands. Mark scheme (1 mark). B1: D (At constant volume the gas pressure rises with temperature and could burst the can).', 1),
('fc569675-f071-5b57-964f-3ced5cfaa697', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 21, 21, 'A gas syringe holds 150 cm³ of gas at 300 K. The gas is cooled at constant pressure to 200 K. Calculate the new volume.', NULL, 1, 'numeric'::answer_type, '100', 'cm³', false, NULL, false, NULL, 'V₂ = V₁T₂/T₁ = 150 × 200 ÷ 300 = 100 cm³. Mark scheme (2 marks). C1: V ∝ T. A1: V = 100 cm³.', 2),
('f53bb85c-dc87-5ab6-bb0c-e87bc0616e7b', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 22, 22, 'The coldest air temperature measured at a polar research station was −89 °C. Express this temperature in kelvin.', NULL, 1, 'numeric'::answer_type, '184', 'K', false, NULL, false, NULL, 'T = −89 + 273 = 184 K. Mark scheme (1 mark). A1: T = 184 K.', 1),
('f3149a20-f3c3-50b8-8bc1-1fb33f6db6e2', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 23, 23, 'In an experiment to investigate the pressure law, a flask of air is heated in a water bath. Why must the flask be completely under the water?', NULL, 1, 'multiple_choice'::answer_type, 'So that all of the air is at the measured water temperature', NULL, false, NULL, false, NULL, 'Any part of the gas outside the bath would be at a different temperature, so p would not match the measured T. Mark scheme (1 mark). B1: B (So that all of the air is at the measured water temperature).', 1),
('f7cadc10-9af0-5e05-9049-cee6e6e458d8', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 24, 24, 'A gas at 27 °C occupies 0.50 m³. It is heated at constant pressure until its volume is 0.75 m³. Calculate its final temperature in °C.', NULL, 2, 'numeric'::answer_type, '177', '°C', false, NULL, false, NULL, 'T₁ = 27 + 273 = 300 K. T₂ = 300 × 0.75 ÷ 0.50 = 450 K. In °C: 450 − 273 = 177. Mark scheme (3 marks). C1: T₁ in kelvin. C1: T₂ = T₁V₂/V₁. A1: θ = 177 °C.', 3),
('c551572c-7c8d-500d-a6bb-9f4bd78bad71', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 25, 25, 'A light bulb is filled with argon at 0.80 × 10⁵ Pa at 20 °C. The glass is designed to withstand a gas pressure of 2.0 × 10⁵ Pa. Calculate the highest mean gas temperature allowed when the bulb is lit.', NULL, 2, 'numeric'::answer_type, '732.5', 'K', false, NULL, false, NULL, 'T₂ = T₁p₂/p₁ = 293 × 2.0 × 10⁵ ÷ 0.80 × 10⁵ = 732 K. Mark scheme (3 marks). C1: T₁ = 293 K. C1: p ∝ T. A1: T = 732 K.', 3),
('b42935b5-f688-5ba4-8be9-692cb9879f35', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 26, 26, 'Two samples of the same gas are each heated at the same constant pressure. Graphs of volume against thermodynamic temperature are straight lines through the origin, but one line is steeper. What does the steeper line show?', NULL, 2, 'multiple_choice'::answer_type, 'That sample contains more gas (more moles)', NULL, false, NULL, false, NULL, 'V/T = nR/p, so at the same pressure a larger gradient means a larger amount of gas. A lower pressure would also steepen the line, but the pressures here are equal. Mark scheme (3 marks). C1: gradient = nR/p. C1: same p, so larger n. A1: C (That sample contains more gas (more moles)).', 3),
('2d5290d4-3306-591f-8fda-32bb43a5c29c', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 27, 27, 'A fixed mass of gas is heated at constant pressure from 0 °C to 100 °C. Calculate the percentage increase in its volume.', NULL, 2, 'numeric'::answer_type, '36.63', '%', false, NULL, false, NULL, 'V₂/V₁ = 373 ÷ 273 = 1.366. Percentage increase = 100 ÷ 273 × 100 = 36.6 %. Mark scheme (3 marks). C1: temperatures in kelvin. C1: ratio of volumes. A1: increase = 36.6%.', 3),
('12805d3a-eabc-5952-a48e-c664a2dff47f', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 28, 28, 'In a Charles''s-law experiment, a trapped sample of air has a volume of 48.0 cm³ at 20 °C and 57.8 cm³ at 80 °C. Assuming the volume varies linearly with temperature, estimate the value of absolute zero in °C.', NULL, 2, 'numeric'::answer_type, '-273.9', '°C', false, NULL, true, NULL, 'Gradient = (57.8 − 48.0) ÷ (80 − 20) = 0.1633 cm³ per °C. V = 0 when θ₀ = 20 − 48.0 ÷ 0.1633 = −274 °C. Mark scheme (4 marks). C1: gradient of V against θ. C1: V = 0 at intercept. C1: extrapolate from a data point. A1: θ₀ = −274 °C.', 4),
('105c43e7-3fb0-54b8-86fd-276213d10cf4', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 29, 29, 'A tyre gauge measures the pressure above atmospheric. It reads 2.0 × 10⁵ Pa at 7 °C, when atmospheric pressure is 1.0 × 10⁵ Pa. After a drive the air in the tyre is at 37 °C. Assuming the volume is constant, calculate the new gauge reading.', NULL, 2, 'numeric'::answer_type, '2.321e5', 'Pa', false, NULL, false, NULL, 'Absolute pressure p₁ = 2.0 × 10⁵ + 1.0 × 10⁵ = 3.0 × 10⁵ Pa. p₂ = 3.0 × 10⁵ × 310 ÷ 280 = 3.32 × 10⁵ Pa. Gauge reading = 3.321 × 10⁵ − 1.0 × 10⁵ = 2.32 × 10⁵ Pa. Mark scheme (4 marks). C1: convert to absolute pressure. C1: p ∝ T in kelvin. C1: subtract atmospheric pressure. A1: gauge reading = 2.32 × 10⁵ Pa. Common mistake: Applying p ∝ T to the gauge reading itself gives 2.21 × 10⁵ Pa, which is wrong: only absolute pressure is proportional to T.', 4),
('4d9b191b-1a13-5000-b640-9b46261a35fd', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 30, 30, 'A gas at 10 °C is warmed at constant pressure to 20 °C. A student says its volume doubles. By what factor does the volume actually increase?', NULL, 2, 'multiple_choice'::answer_type, 'About 1.04 (an increase of about 3.5 %)', NULL, false, NULL, false, NULL, 'V₂/V₁ = T₂/T₁ = 293 ÷ 283 = 1.035. The student used Celsius temperatures, which are not proportional to volume. Mark scheme (3 marks). C1: convert to kelvin. C1: ratio 293/283. A1: A (About 1.04 (an increase of about 3.5 %)).', 3),
('1b133106-68ca-5aca-9483-f30faf5c8ec5', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 31, 31, 'Air has a density of 1.29 kg m⁻³ at 0 °C. Calculate its density at 30 °C at the same pressure.', NULL, 2, 'numeric'::answer_type, '1.162', 'kg m⁻³', false, NULL, false, NULL, 'At constant p, V ∝ T so ρ ∝ 1/T. ρ₂ = 1.29 × 273 ÷ 303 = 1.16 kg m⁻³. Mark scheme (3 marks). C1: ρ ∝ 1/T at constant p. C1: temperatures in kelvin. A1: ρ = 1.16 kg m⁻³.', 3),
('2f7ddd6e-8b3d-5c53-802e-1aa9c07f0d22', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 32, 32, 'A constant-volume gas thermometer reads 1.00 × 10⁵ Pa when its bulb is in melting ice at 273 K. With the bulb in a hot liquid it reads 1.36 × 10⁵ Pa. Calculate the temperature of the liquid.', NULL, 2, 'numeric'::answer_type, '371.3', 'K', false, NULL, false, NULL, 'T = 273 × 1.36 × 10⁵ ÷ 1.00 × 10⁵ = 371 K. Mark scheme (3 marks). C1: p ∝ T at constant V. C1: ratio of pressures. A1: T = 371 K.', 3),
('2c22a879-610d-5f16-bca2-38403c225a68', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 33, 33, 'A fixed mass of gas in a rigid container is heated. Which statement explains why its pressure increases?', NULL, 2, 'multiple_choice'::answer_type, 'The molecules move faster, so each collision with a wall gives a larger change of momentum and collisions are more frequent', NULL, false, NULL, false, NULL, 'Both the momentum change per collision and the collision rate increase with molecular speed, so the force per unit area rises. Mark scheme (4 marks). C1: faster molecules. C1: larger Δp per collision. C1: more collisions per second. A1: D (The molecules move faster, so each collision with a wall gives a larger change of momentum and collisions are more frequent).', 4),
('f61c90ae-7cbf-5c03-ac9c-314091d30be9', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 34, 34, 'Exhaust gas leaves an engine at 600 K at a rate of 0.020 m³ s⁻¹. It passes through a cooler at constant pressure and leaves at 300 K. Calculate the volume flow rate leaving the cooler.', NULL, 2, 'numeric'::answer_type, '0.01', 'm³ s⁻¹', false, NULL, false, NULL, 'V ∝ T for each second''s worth of gas: flow rate = 0.020 × 300 ÷ 600 = 0.010 m³ s⁻¹. Mark scheme (3 marks). C1: same mass per second. C1: V ∝ T. A1: flow rate = 0.010 m³ s⁻¹.', 3),
('6b3a82d5-d402-53f2-acc1-2f144ca29090', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 35, 35, 'A sealed rigid container of gas starts at 27 °C. It is heated until the pressure has increased by 20 %. Calculate the final temperature in °C.', NULL, 2, 'numeric'::answer_type, '87', '°C', false, NULL, false, NULL, 'T₁ = 300 K. p₂ = 1.20p₁, so T₂ = 300 × 1.20 = 360 K. In °C: 360 − 273 = 87. Mark scheme (4 marks). C1: T₁ = 300 K. C1: p₂/p₁ = 1.20. C1: T₂ = 360 K. A1: θ = 87 °C.', 4),
('85e592c0-83a1-5de9-9b60-677316e44d35', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 36, 36, 'A fixed mass of gas in a rigid container is at 27 °C. To what temperature must it be heated to double its pressure?', NULL, 2, 'multiple_choice'::answer_type, '327 °C', NULL, false, NULL, false, NULL, 'T must double from 300 K to 600 K, which is 327 °C. 54 °C doubles the Celsius value; 600 °C confuses kelvin and Celsius. Mark scheme (3 marks). C1: 27 °C = 300 K. C1: T₂ = 600 K. A1: B (327 °C).', 3),
('580a739c-4709-55fd-bd09-badbaed25fd6', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 37, 37, 'Liquid nitrogen is poured over a rubber balloon holding 4.0 litres of air at 22 °C, and the air inside cools to 77 K at constant pressure. Calculate the volume of the cooled air in litres.', NULL, 2, 'numeric'::answer_type, '1.044', 'litres', false, NULL, false, NULL, 'V₂ = 4.0 × 77 ÷ 295 = 1.04 litres. Mark scheme (3 marks). C1: T₁ = 295 K. C1: V ∝ T. A1: V = 1.04 litres.', 3),
('b729c1dd-e539-53b4-acff-90f8b0ab7e32', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 38, 38, 'A gas occupies 2.0 litres at 1.0 × 10⁵ Pa and 300 K. It is heated to 450 K and compressed to 1.5 litres. Calculate its new pressure.', NULL, 2, 'numeric'::answer_type, '2e5', 'Pa', false, NULL, false, NULL, 'pV/T is constant: p₂ = 1.0 × 10⁵ × 2.0 ÷ 1.5 × 450 ÷ 300 = 2.0 × 10⁵ Pa. Mark scheme (4 marks). C1: p₁V₁/T₁ = p₂V₂/T₂. C1: volume ratio. C1: temperature ratio. A1: p = 2.0 × 10⁵ Pa.', 4),
('ba7789ed-f64c-560e-a2fc-1fdc77e16c67', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 39, 39, 'A glass jar is sealed at 25 °C with air inside at 1.01 × 10⁵ Pa, then put in a fridge at 4 °C. The lid has area 5.0 × 10⁻³ m² and the outside air stays at 1.01 × 10⁵ Pa. Calculate the resultant force on the lid due to the pressure difference.', NULL, 2, 'numeric'::answer_type, '35.59', 'N', false, NULL, false, NULL, 'p₂ = 1.01 × 10⁵ × 277 ÷ 298 = 9.39 × 10⁴ Pa. Pressure difference = 1.01 × 10⁵ − 9.388 × 10⁴ = 7120 Pa. F = 7117 × 5.0 × 10⁻³ = 35.6 N. Mark scheme (4 marks). C1: temperatures in kelvin. C1: new pressure. C1: F = Δp × A. A1: F = 35.6 N.', 4),
('593fbbf6-0f69-542e-b50f-0f3a3f2df16e', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 40, 40, 'Graphs of pressure against thermodynamic temperature are drawn for the same mass of gas held at two different fixed volumes. How do the lines compare?', NULL, 2, 'multiple_choice'::answer_type, 'Both pass through the origin; the smaller volume gives the steeper line', NULL, false, NULL, false, NULL, 'p/T = nR/V, so the gradient is larger for the smaller volume, and both lines extrapolate to p = 0 at 0 K. Mark scheme (3 marks). C1: gradient = nR/V. C1: smaller V, steeper. A1: C (Both pass through the origin; the smaller volume gives the steeper line).', 3),
('6f23adeb-291c-5156-954c-f05be706d576', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 41, 41, 'A fixed mass of gas is at 0 °C. At what temperature, in °C, will it occupy twice its volume if its pressure does not change?', NULL, 2, 'numeric'::answer_type, '273', '°C', false, NULL, false, NULL, 'T₂ = 2 × 273 = 546 K. In °C: 546 − 273 = 273. Mark scheme (3 marks). C1: 0 °C = 273 K. C1: V ∝ T so T doubles. A1: θ = 273 °C.', 3),
('c2758a96-6b99-53f9-88a6-de31a40bcc3c', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 42, 42, 'A student uses a flask of air connected to a pressure gauge to test the pressure law. The results are: θ/°C = 0, 20, 40, 60, 80, 100 and p/kPa = 100.0, 107.3, 114.6, 122.0, 129.3, 136.6. (a) Describe the shape of the graph of p against θ. (b) Calculate the gradient of the graph. (c) Use the gradient to find the temperature, in °C, at which the pressure would be zero. (d) Suggest why the tube from the flask to the gauge should be short. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '-273.2', '°C', false, NULL, true, NULL, '(a) A straight line with a positive intercept on the pressure axis. (b) Gradient = (136.6 − 100.0) ÷ (100 − 0) = 0.366 kPa per °C. (c) p = 0 when θ = −100.0 ÷ 0.366 = −273 °C. (d) Air in the tube is not at the bath temperature, so a long tube adds gas that is not heated, giving pressures that are too low. Mark scheme (6 marks). B1: straight line, not through the origin. C1: gradient from the data. C1: θ = −intercept ÷ gradient. B1: air in tube not heated. M1: compares with absolute zero. A1: θ₀ = −273 °C.', 6),
('5f38a971-a9c5-5289-b36a-2b3fb9b6896b', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 43, 43, 'A hot-air balloon envelope has a fixed volume of 2800 m³ and is open at the bottom, so the air inside stays at atmospheric pressure. The air inside is heated from 15 °C to 100 °C. The density of air at 15 °C is 1.23 kg m⁻³. (a) Calculate the mass of air in the envelope at 15 °C. (b) Calculate the fraction of this air that remains inside at 100 °C. (c) Calculate the mass of air pushed out of the envelope. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '784.8', 'kg', false, NULL, false, NULL, '(a) m₁ = 1.23 × 2800 = 3440 kg. (b) At constant p, ρ ∝ 1/T, so the fraction remaining = 288 ÷ 373 = 0.7721. (c) Mass pushed out = 3440 × (1 − 0.7721) = 785 kg. Mark scheme (5 marks). C1: m = ρV. C1: temperatures in kelvin. M1: fraction remaining = T₁/T₂. C1: mass expelled. A1: m = 785 kg.', 5),
('06887bb6-2b6c-56d6-916f-122d54a4d635', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 44, 44, 'A constant-volume gas thermometer is calibrated at the triple point of water, 273.16 K, where the gas pressure is 6.80 × 10⁴ Pa. When the bulb is placed in boiling liquid X the pressure is 1.71 × 10⁵ Pa. (a) Calculate the boiling point of X in kelvin. (b) Express this in °C. (c) Explain why a gas thermometer gives the most reliable results when the gas is at low pressure. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '686.9', 'K', false, NULL, false, NULL, '(a) T = 273.16 × 1.71 × 10⁵ ÷ 6.80 × 10⁴ = 687 K. (b) 686.9 − 273.15 = 414 °C. (c) At low pressure the molecules are far apart, so intermolecular forces and molecular volume are negligible and the gas behaves ideally: p is then exactly proportional to T. Mark scheme (5 marks). C1: p ∝ T at constant V. C1: substitution. C1: conversion to °C. B1: ideal behaviour at low pressure. A1: T = 687 K.', 5),
('846b554f-1318-511a-ba8b-b14fc9686b9c', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 45, 45, 'Two glass bulbs, each of volume 1.0 litre, are joined by a narrow tube of negligible volume. Initially both bulbs are at 273 K and the gas inside is at 1.0 × 10⁵ Pa. Bulb A is then kept at 273 K while bulb B is heated to 373 K. (a) Explain why the pressure is the same in both bulbs. (b) Explain why gas moves from B to A. (c) Calculate the new pressure. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.155e5', 'Pa', false, NULL, false, NULL, '(a) The bulbs are connected, so gas flows until there is no pressure difference. (b) At the same pressure, hot gas has a lower density, so less gas stays in B. (c) The total amount of gas is constant: p(V/273 + V/373) = 2 × 1.0 × 10⁵ × V/273. Cancelling V: p = 2.0 × 10⁵ ÷ (1 + 273 ÷ 373) = 1.15 × 10⁵ Pa. Mark scheme (6 marks). B1: same pressure when connected. B1: hot gas less dense. M1: total n = pV/RT summed over both bulbs. C1: n constant equation. C1: rearrangement. A1: p = 1.15 × 10⁵ Pa.', 6),
('224d3481-f1eb-52cb-96cb-4cbb405ec5a2', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 46, 46, 'A tyre contains air at an absolute pressure of 2.6 × 10⁵ Pa on a winter morning at −5 °C. Later, standing in the sun, the air warms to 35 °C at constant volume. A safety valve lets air out whenever the pressure would exceed 2.9 × 10⁵ Pa. (a) Calculate the pressure the air would reach at 35 °C if no air escaped. (b) Calculate the percentage of the air that escapes through the valve. Give only the answer to (b), in %.', NULL, 3, 'numeric'::answer_type, '2.947', '%', false, NULL, false, NULL, '(a) p = 2.6 × 10⁵ × 308 ÷ 268 = 2.99 × 10⁵ Pa, which is above 2.9 × 10⁵ Pa. (b) At fixed V and T, n ∝ p, so the fraction remaining = 2.9 × 10⁵ ÷ 2.988 × 10⁵ = 0.9705. Percentage escaping = (1 − 0.9705) × 100 = 2.95 %. Mark scheme (5 marks). C1: temperatures in kelvin. C1: p at 35 °C. M1: n ∝ p at fixed V and T. C1: fraction remaining. A1: percentage = 2.95%.', 5),
('9c05d33d-85d6-584b-9c3a-18d843c394ab', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 47, 47, '(a) Show that, for a fixed mass of gas at constant pressure, the volume increases by 1/273 of its value at 0 °C for each 1 °C rise in temperature. (b) A gas occupies 546 cm³ at 0 °C. Use this result to calculate its volume at 50 °C at the same pressure. (c) Explain why the same rule cannot be applied using the volume at 20 °C as the reference. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '646', 'cm³', false, NULL, false, NULL, '(a) V ∝ T, so V = V₀(273 + θ)/273 = V₀ + V₀θ/273: each 1 °C adds V₀/273. (b) V = 546 × 323 ÷ 273 = 646 cm³. (c) The rule is a fraction of the volume at 0 °C; at 20 °C the volume is larger, so each degree adds 1/293 of that volume instead. Mark scheme (5 marks). M1: V ∝ T with T = θ + 273. B1: V₀/273 per degree. C1: substitution. B1: fraction depends on reference temperature. A1: V = 646 cm³.', 5),
('07cef3fd-9198-5551-b28b-23b48acc44e7', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 48, 48, 'A capillary tube of uniform bore traps a thread of air under a short index of mercury, so the air stays at atmospheric pressure. The tube is heated in a water bath. Results: θ/°C = 10, 30, 50, 70, 90 and air-column length L/cm = 5.66, 6.06, 6.46, 6.86, 7.26. (a) Explain why L is proportional to the volume of the air. (b) Calculate the gradient of the graph of L against θ. (c) Use the graph to estimate absolute zero in °C. (d) State whether these results support Charles''s law and explain why. (e) Suggest why the water must be stirred. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '-273', '°C', false, NULL, true, NULL, '(a) V = cross-sectional area × L, and the area is constant. (b) Gradient = (7.26 − 5.66) ÷ (90 − 10) = 0.020 cm per °C. (c) L = 0 when θ = 10 − 5.66 ÷ 0.020 = −273 °C. (d) Yes: L increases linearly with θ and extrapolates to zero at about −273 °C, so V ∝ T in kelvin. (e) Stirring keeps the water, and therefore the air, at a uniform, measured temperature. Mark scheme (7 marks). B1: uniform bore so V ∝ L. C1: gradient. C1: intercept formula. B1: linear. B1: zero at −273 °C so V ∝ T. B1: uniform temperature. A1: θ₀ = −273 °C.', 7),
('1e4ad14f-bdb6-5fe6-a69a-59d213cc9b65', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 49, 49, 'A weather balloon holds 8.0 m³ of helium at ground level, where the pressure is 1.0 × 10⁵ Pa and the temperature is 290 K. It rises to a height where the pressure is 2.5 × 10⁴ Pa and the temperature is 220 K. (a) Calculate the volume of the balloon at this height. (b) The balloon bursts if its volume exceeds 30 m³. State whether it bursts at this height and explain why it expands less than Boyle''s law alone predicts. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '24.28', 'm³', false, NULL, false, NULL, '(a) V₂ = V₁ × (p₁/p₂) × (T₂/T₁) = 8.0 × 4.0 × 220 ÷ 290 = 24.3 m³. (b) It does not burst yet: 24.3 m³ is below 30 m³. The fall in temperature reduces the volume, partly offsetting the expansion due to the lower pressure. Mark scheme (5 marks). C1: pV/T constant. C1: pressure ratio 4.0. C1: temperature ratio. B1: comparison with 30 m³ and effect of cooling. A1: V = 24.3 m³.', 5),
('18dc04fe-3dc6-5d02-a75f-32c1dbdee8b4', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'b9eabbea-06f6-441f-84b6-f328fbc895cb', 'a-level', '20.5', '9702 coursebook 20.5 · Changing temperature', 50, 50, 'A conical flask is closed with a rubber bung at 17 °C, trapping air at atmospheric pressure, 1.0 × 10⁵ Pa. The bung is pushed out when the pressure inside exceeds the pressure outside by 0.30 × 10⁵ Pa. The flask is heated slowly. (a) Calculate the temperature, in kelvin, at which the bung is pushed out. (b) Express this in °C. (c) The glass expands slightly when heated. State and explain whether this makes the actual temperature higher or lower than your answer to (a). Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '377', 'K', false, NULL, false, NULL, '(a) The bung leaves when p = 1.0 × 10⁵ + 0.30 × 10⁵ = 1.30 × 10⁵ Pa. T = 290 × 1.30 × 10⁵ ÷ 1.0 × 10⁵ = 377 K. (b) 377 − 273 = 104 °C. (c) Higher: the larger volume means a higher temperature is needed to reach the same pressure. Mark scheme (5 marks). C1: required pressure 1.30 × 10⁵ Pa. C1: p ∝ T. C1: conversion to °C. B1: higher, because V increases. A1: T = 377 K.', 5)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('0a435aa1-1162-5f7e-b6ff-20670df9cdb6', 'a0f5eae1-7316-50ca-adf7-cc30fb209b9a', 'For a fixed mass of gas at constant temperature, the volume is inversely proportional to the pressure', 'A', false, 0),
('5c9dd384-c850-5c60-a259-3002c6f14f53', 'a0f5eae1-7316-50ca-adf7-cc30fb209b9a', 'For a fixed mass of gas at constant pressure, the volume is directly proportional to the Celsius temperature', 'B', false, 1),
('64f055c6-f3b3-5348-bc2a-86703a950eda', 'a0f5eae1-7316-50ca-adf7-cc30fb209b9a', 'For a fixed mass of gas at constant pressure, the volume is directly proportional to the thermodynamic temperature', 'C', true, 2),
('14831b74-bf1e-5324-9559-d5b77a2b5540', 'a0f5eae1-7316-50ca-adf7-cc30fb209b9a', 'For a fixed mass of gas at constant volume, the pressure is inversely proportional to the temperature', 'D', false, 3),
('79f6bb2e-50af-556a-9563-15f8791f016b', '72689b39-2b43-5618-9f7f-c67829fb8261', 'The temperature at which an ideal gas would exert no pressure, because its molecules would have minimum (zero) kinetic energy', 'A', true, 0),
('36978095-7e59-5317-a56e-d77891e22a20', '72689b39-2b43-5618-9f7f-c67829fb8261', 'The temperature at which water freezes', 'B', false, 1),
('16134966-7338-572e-8c76-ed6c5228fab3', '72689b39-2b43-5618-9f7f-c67829fb8261', 'The lowest temperature reached on Earth', 'C', false, 2),
('484939c6-ff53-5d2b-8f26-7c1cffd65117', '72689b39-2b43-5618-9f7f-c67829fb8261', 'The temperature at which all gases turn to liquid', 'D', false, 3),
('25023480-e975-5f41-bb52-b9c221fb3b79', 'bbdcc5be-6581-5548-9e6c-a802d2aa9664', 'At 0 °C', 'A', false, 0),
('d733a3ab-e10f-50f9-b81e-90d0a7b7576f', 'bbdcc5be-6581-5548-9e6c-a802d2aa9664', 'At about −100 °C', 'B', false, 1),
('bac37ca1-d9d6-5587-a7e1-3d5f5b726992', 'bbdcc5be-6581-5548-9e6c-a802d2aa9664', 'It never meets the axis', 'C', false, 2),
('3f6f8be0-e0fa-555d-bfae-368f6b2b0f74', 'bbdcc5be-6581-5548-9e6c-a802d2aa9664', 'At about −273 °C', 'D', true, 3),
('1169729e-631c-56a1-a134-a4aae048067c', '366bfc27-c22e-5d1d-a2ae-6fdaa55117da', 'Volume against temperature in °C', 'A', false, 0),
('f9ea8a9b-8604-5e73-8df4-221a2db4b303', '366bfc27-c22e-5d1d-a2ae-6fdaa55117da', 'Volume against thermodynamic temperature in kelvin', 'B', true, 1),
('078ba313-d9d5-5696-9124-4279f8a68c49', '366bfc27-c22e-5d1d-a2ae-6fdaa55117da', 'Volume against pressure', 'C', false, 2),
('18e547a0-29d6-543e-a668-a634ae2fe8be', '366bfc27-c22e-5d1d-a2ae-6fdaa55117da', 'Pressure against volume', 'D', false, 3),
('8b5e8f8d-35a1-5477-b25f-e51e8efdf67c', '926f5660-3c06-551d-b1d6-5275302ddeb5', 'Gases do not expand when heated', 'A', false, 0),
('1d172c0f-edbc-5f02-a5b1-b2aff9b1c437', '926f5660-3c06-551d-b1d6-5275302ddeb5', 'The pressure must double instead', 'B', false, 1),
('b16adf2a-543e-5f8c-acd6-ee9cc65d6bd8', '926f5660-3c06-551d-b1d6-5275302ddeb5', 'Its thermodynamic temperature only rises from 293 K to 313 K', 'C', true, 2),
('307dafce-2a30-559b-b8d9-19b8b93c17da', '926f5660-3c06-551d-b1d6-5275302ddeb5', 'Volume is proportional to the square of the temperature', 'D', false, 3),
('3409dc4e-ae47-5beb-8a63-87ef3a706504', 'aa65b2d5-e065-5dcd-96c8-e1f9487f01c2', 'Pressure and thermodynamic temperature', 'A', true, 0),
('0d578b49-36c0-5a7f-977f-4f6c96c66b1e', 'aa65b2d5-e065-5dcd-96c8-e1f9487f01c2', 'Pressure and Celsius temperature', 'B', false, 1),
('0bfe77e4-8306-5ca8-b0a6-0197987fce2e', 'aa65b2d5-e065-5dcd-96c8-e1f9487f01c2', 'Pressure and volume', 'C', false, 2),
('dfa8720c-bbf9-51c9-9032-8f076735d5a4', 'aa65b2d5-e065-5dcd-96c8-e1f9487f01c2', 'Volume and Celsius temperature', 'D', false, 3),
('23983c11-885c-5c56-b54c-30b58ccf046c', '4f2d8e19-6f12-5902-8544-b819fe97af7d', 'Heat makes the gas molecules expand and crack the can', 'A', false, 0),
('f88eab3d-4016-574d-a708-ddd9345ff0aa', '4f2d8e19-6f12-5902-8544-b819fe97af7d', 'The gas becomes heavier when heated', 'B', false, 1),
('cbeda52d-b8c7-5f4d-ac3e-1c121c477291', '4f2d8e19-6f12-5902-8544-b819fe97af7d', 'The gas turns into a liquid when heated', 'C', false, 2),
('c546261a-5155-5cef-b93a-2cf44f6a01f5', '4f2d8e19-6f12-5902-8544-b819fe97af7d', 'At constant volume the gas pressure rises with temperature and could burst the can', 'D', true, 3),
('f3aaf39c-6746-5fb9-8b11-1371690abaf1', 'f3149a20-f3c3-50b8-8bc1-1fb33f6db6e2', 'So that the air cannot escape', 'A', false, 0),
('128f567e-5ba7-5b5d-bd9d-ec0f848e4e44', 'f3149a20-f3c3-50b8-8bc1-1fb33f6db6e2', 'So that all of the air is at the measured water temperature', 'B', true, 1),
('42714520-6ac6-53d4-b728-a23d33a90fc9', 'f3149a20-f3c3-50b8-8bc1-1fb33f6db6e2', 'To keep the pressure constant', 'C', false, 2),
('3b01ce1e-90a1-5a00-87df-02f77b4244c1', 'f3149a20-f3c3-50b8-8bc1-1fb33f6db6e2', 'To stop the flask from expanding', 'D', false, 3),
('7ba3bea7-55bf-5b2f-93cd-33b100581e4f', 'b42935b5-f688-5ba4-8be9-692cb9879f35', 'That sample is at a higher temperature', 'A', false, 0),
('e38dde6d-4ce5-54da-ad95-ef4caec4dfca', 'b42935b5-f688-5ba4-8be9-692cb9879f35', 'That sample has a lower pressure but the same amount', 'B', false, 1),
('2c34a461-641d-5671-9f62-c2c29c2845a7', 'b42935b5-f688-5ba4-8be9-692cb9879f35', 'That sample contains more gas (more moles)', 'C', true, 2),
('4c27a9ef-ba7d-5f42-b295-df516656a595', 'b42935b5-f688-5ba4-8be9-692cb9879f35', 'That sample does not obey Charles''s law', 'D', false, 3),
('3426c7b4-0ec7-58d9-acac-9370d66b8e89', '4d9b191b-1a13-5000-b640-9b46261a35fd', 'About 1.04 (an increase of about 3.5 %)', 'A', true, 0),
('de5ef435-7f87-5f27-86f1-c6057f8e9488', '4d9b191b-1a13-5000-b640-9b46261a35fd', '2.0', 'B', false, 1),
('db6da060-10de-5734-9a30-c9dd5cde3fa1', '4d9b191b-1a13-5000-b640-9b46261a35fd', '1.10', 'C', false, 2),
('718ea29d-d9f3-504b-9e10-4e73c4582055', '4d9b191b-1a13-5000-b640-9b46261a35fd', '0.5', 'D', false, 3),
('2cc07aea-c140-52bf-a741-9fdbc1af8bb2', '2c22a879-610d-5f16-bca2-38403c225a68', 'The molecules expand, so they hit the walls more often', 'A', false, 0),
('f81d675c-b989-5637-af22-78180febe4e1', '2c22a879-610d-5f16-bca2-38403c225a68', 'The number of molecules increases', 'B', false, 1),
('0a653beb-8835-593d-b661-d64672e64799', '2c22a879-610d-5f16-bca2-38403c225a68', 'The molecules become heavier and press harder on the walls', 'C', false, 2),
('82c8f7e4-49a9-55d0-8c38-e1759cdf257d', '2c22a879-610d-5f16-bca2-38403c225a68', 'The molecules move faster, so each collision with a wall gives a larger change of momentum and collisions are more frequent', 'D', true, 3),
('4650f4d3-cea6-5d6c-a1bb-8975854ace36', '85e592c0-83a1-5de9-9b60-677316e44d35', '54 °C', 'A', false, 0),
('4a9d81a6-6412-5184-ac5e-262c941c1864', '85e592c0-83a1-5de9-9b60-677316e44d35', '327 °C', 'B', true, 1),
('5dcc65cf-7173-51db-9b56-2e92d483e64d', '85e592c0-83a1-5de9-9b60-677316e44d35', '600 °C', 'C', false, 2),
('85ee77e2-dc1a-5cf1-828c-28f9c11a0044', '85e592c0-83a1-5de9-9b60-677316e44d35', '−123 °C', 'D', false, 3),
('96567292-1aae-52d6-818f-e917e45c2588', '593fbbf6-0f69-542e-b50f-0f3a3f2df16e', 'Both pass through the origin; the larger volume gives the steeper line', 'A', false, 0),
('d44360c4-b73d-53d6-b849-63b00f6fcd32', '593fbbf6-0f69-542e-b50f-0f3a3f2df16e', 'They are parallel lines with different intercepts', 'B', false, 1),
('32267cc4-f177-5d66-8468-89507086585e', '593fbbf6-0f69-542e-b50f-0f3a3f2df16e', 'Both pass through the origin; the smaller volume gives the steeper line', 'C', true, 2),
('8e86a80c-b1dd-5fb8-a37d-835b2e0ef8f3', '593fbbf6-0f69-542e-b50f-0f3a3f2df16e', 'They meet the temperature axis at different temperatures', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('46254ded-3c44-5e12-97a6-b920a704936e', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 9, 9, 'A flask holds 0.50 mol of an ideal gas in a volume of 0.012 m³ at 290 K. Calculate the pressure. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '1.004e5', 'Pa', false, NULL, false, NULL, 'p = nRT/V = 0.50 × 8.31 × 290 ÷ 0.012 = 1.00 × 10⁵ Pa. Mark scheme (2 marks). C1: p = nRT/V. A1: p = 1.00 × 10⁵ Pa.', 2),
('5a5c6727-2563-5794-826e-437b7bcf3e1b', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 10, 10, 'A scuba tank of volume 0.012 m³ is filled with air at 2.0 × 10⁷ Pa and 290 K. Calculate the amount of air in moles. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '99.59', 'mol', false, NULL, false, NULL, 'n = pV/RT = 2.0 × 10⁷ × 0.012 ÷ (8.31 × 290) = 99.6 mol. Mark scheme (2 marks). C1: n = pV/RT. A1: n = 99.6 mol.', 2),
('2c2f91bd-9210-526e-90b0-55d44c2ad22d', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 11, 11, 'Calculate the volume occupied by 1.0 mol of an ideal gas at 273 K and 1.01 × 10⁵ Pa. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '0.02246', 'm³', false, NULL, false, NULL, 'V = nRT/p = 1.0 × 8.31 × 273 ÷ 1.01 × 10⁵ = 0.0225 m³. Mark scheme (2 marks). C1: V = nRT/p. A1: V = 0.0225 m³.', 2),
('bcb35dc8-1957-5199-ba3a-cea63a459bb2', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 12, 12, 'What is the SI unit of the molar gas constant R?', NULL, 1, 'multiple_choice'::answer_type, 'J mol⁻¹ K⁻¹', NULL, false, NULL, false, NULL, 'R = pV/(nT): (Pa m³) ÷ (mol K) = J mol⁻¹ K⁻¹. Mark scheme (1 mark). B1: C (J mol⁻¹ K⁻¹).', 1),
('9aa91e31-0c0a-5472-b5a8-3e8f7386090d', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 13, 13, 'In the equation pV = NkT, what does N represent?', NULL, 1, 'multiple_choice'::answer_type, 'The number of molecules of gas', NULL, false, NULL, false, NULL, 'pV = NkT counts molecules; pV = nRT counts moles, with nR = Nk. Mark scheme (1 mark). B1: A (The number of molecules of gas).', 1),
('6c694c2b-3b4b-5fe6-83a0-163ff2af9372', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 14, 14, 'A cylinder contains 0.25 mol of gas in a volume of 5.0 × 10⁻³ m³ at a pressure of 1.2 × 10⁵ Pa. Calculate the temperature of the gas. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '288.8', 'K', false, NULL, false, NULL, 'T = pV/nR = 1.2 × 10⁵ × 5.0 × 10⁻³ ÷ (0.25 × 8.31) = 289 K. Mark scheme (2 marks). C1: T = pV/nR. A1: T = 289 K.', 2),
('d4876e6f-aff4-52ed-96ff-32aca36da317', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 15, 15, 'What is meant by an ideal gas?', NULL, 1, 'multiple_choice'::answer_type, 'A gas that obeys pV = nRT exactly at all pressures, volumes and temperatures', NULL, false, NULL, false, NULL, 'Real gases approach ideal behaviour at low pressure and high temperature. Mark scheme (1 mark). B1: D (A gas that obeys pV = nRT exactly at all pressures, volumes and temperatures).', 1),
('81197660-9413-5298-bf5d-5b315a5f721e', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 16, 16, 'Calculate the number of gas molecules in 1.0 m³ of a gas at 1.0 × 10⁵ Pa and 300 K. Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 1, 'numeric'::answer_type, '2.415e25', NULL, false, NULL, false, NULL, 'N = pV/kT = 1.0 × 10⁵ × 1.0 ÷ (1.38 × 10⁻²³ × 300) = 2.42 × 10²⁵. Mark scheme (2 marks). C1: N = pV/kT. A1: N = 2.42 × 10²⁵.', 2),
('8486ca27-e599-565e-9ed3-4d5028a2507f', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 17, 17, 'Which equation correctly links the molar gas constant R, the Boltzmann constant k and the Avogadro constant N_A?', NULL, 1, 'multiple_choice'::answer_type, 'R = N_A k', NULL, false, NULL, false, NULL, 'nR = Nk and N = nN_A, so R = N_A k. Mark scheme (1 mark). B1: B (R = N_A k).', 1),
('439ce4b9-57a9-5e99-b037-47944081e9d9', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 18, 18, 'A gas bottle of volume 0.020 m³ contains 4.0 mol of propane vapour at 300 K. Calculate the pressure, treating the vapour as an ideal gas. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '4.986e5', 'Pa', false, NULL, false, NULL, 'p = nRT/V = 4.0 × 8.31 × 300 ÷ 0.020 = 4.99 × 10⁵ Pa. Mark scheme (2 marks). C1: p = nRT/V. A1: p = 4.99 × 10⁵ Pa.', 2),
('ac1e8884-26be-5df8-b0e4-1499b11b872e', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 19, 19, 'Under which conditions does a real gas behave most like an ideal gas?', NULL, 1, 'multiple_choice'::answer_type, 'Low pressure and high temperature', NULL, false, NULL, false, NULL, 'At low pressure the molecules are far apart; at high temperature they move fast, so intermolecular forces matter less. Mark scheme (1 mark). B1: C (Low pressure and high temperature).', 1),
('23df4365-a338-5806-bf23-b9a9c75f8ace', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 20, 20, 'A balloon contains 2.0 g of helium (molar mass 4.0 g mol⁻¹) at 1.0 × 10⁵ Pa and 300 K. Calculate the volume of the balloon. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '0.01247', 'm³', false, NULL, false, NULL, 'n = 2.0 ÷ 4.0 = 0.50 mol. V = nRT/p = 0.50 × 8.31 × 300 ÷ 1.0 × 10⁵ = 0.0125 m³. Mark scheme (2 marks). C1: n = m/M. A1: V = 0.0125 m³.', 2),
('0b0f7705-01f5-5b73-8bf8-7725d1cac903', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 21, 21, 'The pressure and the thermodynamic temperature of a fixed amount of ideal gas are both doubled. What happens to its volume?', NULL, 1, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'V = nRT/p: doubling both T and p leaves V unchanged. Mark scheme (1 mark). B1: A (It stays the same).', 1),
('5ffbaa3c-5642-5f21-870d-88a24cfe7852', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 22, 22, 'A container of volume 0.010 m³ holds 3.0 × 10²³ gas molecules at 350 K. Calculate the pressure. Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 1, 'numeric'::answer_type, '1.449e5', 'Pa', false, NULL, false, NULL, 'p = NkT/V = 3.0 × 10²³ × 1.38 × 10⁻²³ × 350 ÷ 0.010 = 1.45 × 10⁵ Pa. Mark scheme (2 marks). C1: p = NkT/V. A1: p = 1.45 × 10⁵ Pa.', 2),
('f2957c25-afe3-5129-8132-95aa94712594', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 23, 23, 'Which quantity is NOT needed to calculate the amount, in moles, of an ideal gas using pV = nRT?', NULL, 1, 'multiple_choice'::answer_type, 'The molar mass of the gas', NULL, false, NULL, false, NULL, 'n = pV/RT depends only on p, V and T; the molar mass is needed only to convert n into a mass. Mark scheme (1 mark). B1: D (The molar mass of the gas).', 1),
('e4c4a6e6-f697-5e58-9643-8472a2d0b9f2', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 24, 24, 'Calculate the value of nRT for 2.0 mol of an ideal gas at 300 K, which equals pV for the gas. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '4986', 'J', false, NULL, false, NULL, 'pV = nRT = 2.0 × 8.31 × 300 = 4990 J. Mark scheme (1 mark). A1: pV = 4990 J.', 1),
('962e7e94-548c-52c9-8478-f5d606c414a1', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 25, 25, 'A laboratory flask of volume 1.0 litre contains air at 1.0 × 10⁵ Pa and 20 °C. Calculate the amount of air in the flask, in moles. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '0.04107', 'mol', false, NULL, false, NULL, 'V = 1.0 × 10⁻³ m³ and T = 293 K. n = pV/RT = 1.0 × 10⁵ × 1.0 × 10⁻³ ÷ (8.31 × 293) = 0.0411 mol. Mark scheme (2 marks). C1: units converted (m³, K). A1: n = 0.0411 mol.', 2),
('0aaf3de9-e93b-5463-90c6-1dd12e8175d2', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 26, 26, 'A room measures 5.0 m × 4.0 m × 2.5 m. The air in it is at 1.0 × 10⁵ Pa and 20 °C, and its mean molar mass is 0.029 kg mol⁻¹. Calculate the mass of air in the room. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '59.55', 'kg', false, NULL, false, NULL, 'V = 5.0 × 4.0 × 2.5 = 50 m³. n = pV/RT = 1.0 × 10⁵ × 50 ÷ (8.31 × 293) = 2050 mol. m = nM = 2054 × 0.029 = 59.6 kg. Mark scheme (3 marks). C1: n = pV/RT. C1: m = nM. A1: m = 59.6 kg.', 3),
('dd7388b5-8da3-5eab-b17f-0aae89987c96', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 27, 27, 'Calculate the density of carbon dioxide (molar mass 0.044 kg mol⁻¹) at 1.0 × 10⁵ Pa and 300 K. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '1.765', 'kg m⁻³', false, NULL, false, NULL, 'ρ = m/V = pM/RT = 1.0 × 10⁵ × 0.044 ÷ (8.31 × 300) = 1.76 kg m⁻³. Mark scheme (3 marks). M1: ρ = pM/RT from pV = (m/M)RT. C1: substitution. A1: ρ = 1.76 kg m⁻³.', 3),
('be5f3d3d-e6a7-501a-9541-9259337c8eb4', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 28, 28, 'A gas has a density of 1.78 kg m⁻³ at 273 K and 1.01 × 10⁵ Pa. Calculate its molar mass and suggest which gas it could be. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '0.03998', 'kg mol⁻¹', false, NULL, false, NULL, 'M = ρRT/p = 1.78 × 8.31 × 273 ÷ 1.01 × 10⁵ = 0.0400 kg mol⁻¹: argon (0.040 kg mol⁻¹). Mark scheme (4 marks). M1: M = ρRT/p. C1: substitution. B1: identifies argon. A1: M = 0.0400 kg mol⁻¹.', 4),
('268a76a6-13d7-5056-9d4c-45f4c8269b30', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 29, 29, 'In a diesel engine, air at 1.0 × 10⁵ Pa and 300 K is compressed to one eighteenth of its volume, and its pressure rises to 5.0 × 10⁶ Pa. Calculate the temperature of the compressed air.', NULL, 2, 'numeric'::answer_type, '833.3', 'K', false, NULL, false, NULL, 'pV/T is constant: T₂ = T₁ × (p₂/p₁) × (V₂/V₁) = 300 × 50 ÷ 18 = 833 K. Mark scheme (4 marks). C1: p₁V₁/T₁ = p₂V₂/T₂. C1: p ratio 50. C1: V ratio 1/18. A1: T = 833 K.', 4),
('6eded013-2d72-5e4e-b8f9-854390ad6213', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 30, 30, 'Two identical containers are at the same temperature and pressure. One holds hydrogen and the other holds carbon dioxide. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'They contain the same number of molecules', NULL, false, NULL, false, NULL, 'N = pV/kT does not depend on the type of gas. The masses differ because CO₂ molecules are 22 times as massive. Mark scheme (3 marks). C1: N = pV/kT. C1: independent of gas type. A1: B (They contain the same number of molecules).', 3),
('b9f8a720-d117-5930-be57-50287596dedf', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 31, 31, 'A gas cylinder of volume 0.040 m³ is kept at 290 K. Over a week its pressure falls from 1.5 × 10⁷ Pa to 1.2 × 10⁷ Pa because of a slow leak. Calculate the amount of gas lost, in moles. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '49.79', 'mol', false, NULL, false, NULL, 'Δn = ΔpV/RT = (1.5 × 10⁷ − 1.2 × 10⁷) × 0.040 ÷ (8.31 × 290) = 49.8 mol. Mark scheme (3 marks). C1: n ∝ p at fixed V and T. C1: substitution. A1: Δn = 49.8 mol.', 3),
('7e3ca099-74df-5675-9052-2a0f035573c0', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 32, 32, 'A car tyre contains air at 2.4 × 10⁵ Pa at 10 °C. After a fast drive the air is at 45 °C and the tyre has stretched so that its volume is 3.0 % larger. Calculate the new pressure.', NULL, 2, 'numeric'::answer_type, '2.618e5', 'Pa', false, NULL, false, NULL, 'p₂ = p₁ × (T₂/T₁) × (V₁/V₂) = 2.4 × 10⁵ × 318 ÷ 283 ÷ 1.03 = 2.62 × 10⁵ Pa. Mark scheme (4 marks). C1: temperatures in kelvin. C1: V₂ = 1.03V₁. C1: pV/T constant. A1: p = 2.62 × 10⁵ Pa.', 4),
('faeb99f1-e3db-53c8-9a3a-7a5a4c15e033', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 33, 33, 'A student calculates the volume of 1.0 mol of gas at 27 °C and 1.0 × 10⁵ Pa but uses T = 27 in pV = nRT. How does the student''s answer compare with the correct value?', NULL, 2, 'multiple_choice'::answer_type, 'It is about 11 times too small', NULL, false, NULL, false, NULL, 'The correct T is 300 K, so using 27 makes V too small by 300/27 ≈ 11. Mark scheme (3 marks). C1: T should be 300 K. C1: ratio 300/27. A1: C (It is about 11 times too small).', 3),
('9453fe76-5841-58db-b29d-da4ed48dd998', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 34, 34, 'A party balloon of volume 0.80 m³ is filled with helium (molar mass 0.0040 kg mol⁻¹) at 1.02 × 10⁵ Pa and 288 K. Calculate the mass of helium in the balloon. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '0.1364', 'kg', false, NULL, false, NULL, 'n = pV/RT = 1.02 × 10⁵ × 0.80 ÷ (8.31 × 288) = 34.1 mol. m = 34.10 × 0.0040 = 0.136 kg. Mark scheme (3 marks). C1: n = pV/RT. C1: m = nM. A1: m = 0.136 kg.', 3),
('f6b34710-705c-5df0-bc16-4eb7f30fb905', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 35, 35, 'A car airbag inflates to a volume of 0.060 m³ with nitrogen (molar mass 0.028 kg mol⁻¹) at 1.2 × 10⁵ Pa and 300 K. Calculate the mass of nitrogen needed. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '0.08087', 'kg', false, NULL, false, NULL, 'n = pV/RT = 1.2 × 10⁵ × 0.060 ÷ (8.31 × 300) = 2.89 mol. m = nM = 2.888 × 0.028 = 0.0809 kg. Mark scheme (4 marks). C1: pV = nRT rearranged. C1: substitution. C1: m = nM. A1: m = 0.0809 kg.', 4),
('f6dcb77d-5c88-5938-8e42-bd2e140f15f7', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 36, 36, 'For a fixed amount of an ideal gas, a graph of pV (y-axis) against T (x-axis) is a straight line through the origin with gradient 2.5 J K⁻¹. Calculate the amount of gas. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '0.3008', 'mol', false, NULL, false, NULL, 'pV = nRT, so the gradient = nR and n = 2.5 ÷ 8.31 = 0.301 mol. Mark scheme (3 marks). M1: gradient = nR. C1: n = gradient/R. A1: n = 0.301 mol.', 3),
('3cd327c2-19c1-5e0f-bde8-f6dca8e8e685', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 37, 37, 'A rigid container of gas is held at constant volume. The amount of gas in it is doubled while its thermodynamic temperature is halved. What happens to the pressure?', NULL, 2, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'p = nRT/V: doubling n and halving T leaves nT, and so p, unchanged. Mark scheme (4 marks). C1: p ∝ nT at constant V. C1: 2 × ½ = 1. C1: so p unchanged. A1: A (It stays the same).', 4),
('ff9235be-9894-56f9-b8d2-e44c357d66dd', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 38, 38, 'Estimate the number of molecules in 1.0 mm³ of air at 1.0 × 10⁵ Pa and 273 K. Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 2, 'numeric'::answer_type, '2.654e16', NULL, false, NULL, false, NULL, 'V = 1.0 mm³ = 1.0 × 10⁻⁹ m³. N = pV/kT = 1.0 × 10⁵ × 1.0 × 10⁻⁹ ÷ (1.38 × 10⁻²³ × 273) = 2.65 × 10¹⁶. Mark scheme (3 marks). C1: mm³ → m³. C1: N = pV/kT. A1: N = 2.65 × 10¹⁶.', 3),
('6fbf3d83-2c92-5e70-abce-221d80d1615e', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 39, 39, 'A car tyre has an internal volume of 0.025 m³ and contains air at 2.5 × 10⁵ Pa and 15 °C. Calculate the number of air molecules in the tyre. Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 2, 'numeric'::answer_type, '1.573e24', NULL, false, NULL, false, NULL, 'T = 15 + 273 = 288 K. N = pV/kT = 2.5 × 10⁵ × 0.025 ÷ (1.38 × 10⁻²³ × 288) = 1.57 × 10²⁴. Mark scheme (4 marks). C1: T in kelvin. C1: N = pV/kT. C1: substitution. A1: N = 1.57 × 10²⁴.', 4),
('8f30f14c-a0b0-5d63-ab13-54b52c73a724', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 40, 40, 'For a fixed amount of ideal gas at constant pressure, which graph is a straight line through the origin?', NULL, 2, 'multiple_choice'::answer_type, 'Volume against thermodynamic temperature', NULL, false, NULL, false, NULL, 'V = (nR/p)T, so V is proportional to T in kelvin. The V–θ line has an intercept at −273 °C. Mark scheme (3 marks). C1: V = (nR/p)T. C1: T in kelvin. A1: D (Volume against thermodynamic temperature).', 3),
('e27830ef-ccb0-51c0-a655-e1fc88dcdb17', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 41, 41, 'A lit filament lamp contains 0.0040 mol of argon in a volume of 2.0 × 10⁻⁴ m³. The mean temperature of the gas is 600 K. Calculate the pressure of the argon. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '99720', 'Pa', false, NULL, false, NULL, 'p = nRT/V = 0.0040 × 8.31 × 600 ÷ 2.0 × 10⁻⁴ = 9.97 × 10⁴ Pa. Mark scheme (3 marks). C1: p = nRT/V. C1: substitution. A1: p = 9.97 × 10⁴ Pa.', 3),
('fc651536-3fb8-5757-9f8b-f3adb1fe98fc', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 42, 42, 'A rigid container of volume 0.010 m³ holds oxygen (molar mass 0.032 kg mol⁻¹) at 3.0 × 10⁵ Pa and 300 K. (a) Calculate the amount of oxygen. (b) The container is heated to 400 K. A valve releases gas so that the pressure stays at 3.0 × 10⁵ Pa. Calculate the amount of oxygen left in the container. (c) Calculate the mass of oxygen released. Give only the answer to (c). Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '0.009627', 'kg', false, NULL, false, NULL, '(a) n₁ = 3.0 × 10⁵ × 0.010 ÷ (8.31 × 300) = 1.20 mol. (b) n₂ = 3.0 × 10⁵ × 0.010 ÷ (8.31 × 400) = 0.903 mol. (c) Δm = (1.203 − 0.9025) × 0.032 = 0.00963 kg. Mark scheme (6 marks). C1: n = pV/RT. A1: n₁. C1: n₂ at 400 K. M1: Δn = n₁ − n₂. C1: m = ΔnM. A1: Δm = 0.00963 kg.', 6),
('699436b1-9c39-549d-8b68-55a06e14da4b', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 43, 43, 'To find the molar mass of a gas, an evacuated flask of volume 2.50 × 10⁻⁴ m³ is weighed, filled with the gas at 1.01 × 10⁵ Pa and 293 K, and weighed again. Its mass increases by 0.45 g. (a) Calculate the amount of gas in the flask. (b) Calculate the molar mass. (c) Suggest which common gas this is. Give only the answer to (b). Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '0.04339', 'kg mol⁻¹', false, NULL, false, NULL, '(a) n = pV/RT = 1.01 × 10⁵ × 2.50 × 10⁻⁴ ÷ (8.31 × 293) = 0.0104 mol. (b) M = m/n = 4.5 × 10⁻⁴ ÷ 0.01037 = 0.0434 kg mol⁻¹. (c) Carbon dioxide, molar mass 0.044 kg mol⁻¹. Mark scheme (5 marks). C1: n = pV/RT. C1: mass in kg. C1: M = m/n. B1: identifies CO₂. A1: M = 0.0434 kg mol⁻¹.', 5),
('c250e8b3-ef34-5542-a9cb-187abe6ceb80', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 44, 44, 'A bubble of volume 1.2 cm³ is released at a depth of 25 m in a lake, where the water is at 4 °C. It rises to the surface, where the water is at 20 °C and the atmospheric pressure is 1.0 × 10⁵ Pa. The density of water is 1000 kg m⁻³. (a) Calculate the pressure at a depth of 25 m. (b) Calculate the volume of the bubble just below the surface. (c) State one assumption you have made. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '4.382', 'cm³', false, NULL, false, NULL, '(a) p₁ = 1.0 × 10⁵ + 1000 × 9.81 × 25 = 3.45 × 10⁵ Pa. (b) V₂ = V₁ × (p₁/p₂) × (T₂/T₁) = 1.2 × 3.452 × 10⁵ ÷ 1.0 × 10⁵ × 293 ÷ 277 = 4.38 cm³. (c) The amount of gas in the bubble stays the same, and the gas reaches the temperature of the water around it. Mark scheme (6 marks). C1: p = p₀ + ρgh. A1: pressure at depth. C1: pV/T constant. C1: temperatures in kelvin. B1: valid assumption. A1: V = 4.38 cm³.', 6),
('029f2b53-172e-5556-ae22-60d394671495', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 45, 45, 'A very good laboratory vacuum has a pressure of 1.0 × 10⁻¹¹ Pa at 290 K. (a) Calculate the number of molecules per cubic metre. (b) Assuming each molecule occupies a small cube, estimate the mean spacing between molecules. (c) Comment on your answer. Give only the answer to (b), in mm. Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 3, 'numeric'::answer_type, '0.7369 mm', 'mm', false, NULL, false, NULL, '(a) n = p/kT = 1.0 × 10⁻¹¹ ÷ (1.38 × 10⁻²³ × 290) = 2.50 × 10⁹ m⁻³. (b) Volume per molecule = 1 ÷ 2.499 × 10⁹ = 4.00 × 10⁻¹⁰ m³. Spacing = (4.002 × 10⁻¹⁰)^(1/3) = 7.37 × 10⁻⁴ m. In mm: 7.369 × 10⁻⁴ × 1000 = 0.737. (c) Even in this vacuum there are billions of molecules per cubic metre, though they are about a million times further apart than in air. Mark scheme (5 marks). C1: n = p/kT. C1: volume per molecule = 1/n. C1: cube root. B1: sensible comment. A1: d = 0.737 mm.', 5),
('c24b2c5d-ee0a-5fcf-8f3e-ba36076ba613', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 46, 46, 'A fixed amount of gas is held in a rigid vessel of volume 2.0 × 10⁻³ m³. Readings: T/K = 250, 300, 350, 400 and p/kPa = 62.3, 74.8, 87.2, 99.7. (a) Show that the pressure is proportional to the thermodynamic temperature. (b) Calculate the gradient of the graph of p against T. (c) Use the gradient to calculate the amount of gas in the vessel. (d) Calculate the number of molecules. Give only the answer to (c). Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '0.06001', 'mol', false, NULL, false, NULL, '(a) p/T = 62.3 × 10³ ÷ 250 = 249 Pa K⁻¹, and the other readings also give 249 Pa K⁻¹, so p ∝ T. (b) Gradient = (99.7 − 62.3) × 10³ ÷ (400 − 250) = 249 Pa K⁻¹. (c) p = (nR/V)T, so n = gradient × V/R = 249.3 × 2.0 × 10⁻³ ÷ 8.31 = 0.0600 mol. (d) N = 0.06001 × 6.02 × 10²³ = 3.61 × 10²². Mark scheme (6 marks). B1: p/T constant for the readings. C1: gradient. M1: gradient = nR/V. C1: n. C1: N = nN_A. A1: n = 0.0600 mol.', 6),
('cccbc8ec-8991-580f-8d88-91eb99456510', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 47, 47, 'A diver''s cylinder of volume 0.012 m³ holds air at 2.0 × 10⁷ Pa and 290 K. At a depth where the pressure is 3.0 × 10⁵ Pa, the diver breathes 0.020 m³ of air per minute, measured at that pressure and at 290 K. (a) Calculate the amount of air that can be used before the cylinder pressure falls to 5.0 × 10⁶ Pa. (b) Calculate the amount of air the diver uses each minute. (c) Hence calculate how long the diver can stay at this depth, in minutes. Give only the answer to (c). Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '30', 'min', false, NULL, false, NULL, '(a) Usable n = (2.0 × 10⁷ − 5.0 × 10⁶) × 0.012 ÷ (8.31 × 290) = 74.7 mol. (b) Per minute: 3.0 × 10⁵ × 0.020 ÷ (8.31 × 290) = 2.49 mol. (c) t = 74.69 ÷ 2.490 = 30.0 minutes. Mark scheme (5 marks). C1: usable Δp. C1: n = pV/RT. C1: amount per minute. C1: time = total ÷ rate. A1: t = 30.0 min.', 5),
('3a382c78-dced-5800-a6d5-23536c1d96b1', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 48, 48, 'A high-altitude research balloon carries 2.0 kg of helium (molar mass 0.0040 kg mol⁻¹). (a) Calculate the amount of helium. (b) Calculate the volume of the helium at launch, where the pressure is 1.0 × 10⁵ Pa and the temperature is 288 K. (c) Calculate the volume of the helium at its working height, where the pressure is 1.0 × 10³ Pa and the temperature is 220 K. Give only the answer to (c). Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '914.1', 'm³', false, NULL, false, NULL, '(a) n = 2.0 ÷ 0.0040 = 500 mol. (b) V = 500 × 8.31 × 288 ÷ 1.0 × 10⁵ = 12.0 m³. (c) V = 500 × 8.31 × 220 ÷ 1.0 × 10³ = 914 m³. Mark scheme (5 marks). C1: n = m/M. C1: V = nRT/p at launch. C1: new p and T used. C1: substitution. A1: V = 914 m³.', 5),
('4a8923ab-96ca-5582-a5ab-f22076eaf797', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 49, 49, '(a) Show that one mole of an ideal gas occupies about 0.0224 m³ at 273 K and 1.01 × 10⁵ Pa. (b) Use this to calculate the density of oxygen (molar mass 0.032 kg mol⁻¹) at 273 K and 1.01 × 10⁵ Pa. (c) Explain why equal volumes of different gases at the same temperature and pressure contain equal numbers of molecules. Give only the answer to (b). Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '1.425', 'kg m⁻³', false, NULL, false, NULL, '(a) V = nRT/p = 1.0 × 8.31 × 273 ÷ 1.01 × 10⁵ = 0.0225 m³ ≈ 0.0224 m³. (b) ρ = M/V_m = 0.032 ÷ 0.02246 = 1.42 kg m⁻³. (c) N = pV/kT contains no property of the gas, so the same p, V and T give the same N. Mark scheme (5 marks). C1: V = nRT/p. B1: about 0.0224 m³ shown. C1: ρ = M/V_m. B1: N = pV/kT independent of gas. A1: ρ = 1.42 kg m⁻³.', 5),
('bd6af989-e6c1-5f70-bb7c-44af22b2b67d', '468b27d0-3cef-43ee-aeef-09b1a340050f', '2dd6660f-f63e-5078-8c92-9b2c1782553d', 'a-level', '20.6', '9702 coursebook 20.6 · The ideal gas equation', 50, 50, 'In one cylinder of a petrol engine, 5.0 × 10⁻⁴ m³ of fuel–air mixture at 1.0 × 10⁵ Pa and 300 K is compressed to 5.0 × 10⁻⁵ m³, and its pressure rises to 2.0 × 10⁶ Pa. Treat the mixture as an ideal gas. (a) Calculate the amount of gas in the cylinder. (b) Calculate the temperature after compression. (c) The mixture is ignited and its temperature rises to 2400 K at constant volume. Calculate the new pressure. (d) The piston has area 5.0 × 10⁻³ m². Calculate the force on it just after ignition. Give only the answer to (c). Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '8e6', 'Pa', false, NULL, false, NULL, '(a) n = pV/RT = 1.0 × 10⁵ × 5.0 × 10⁻⁴ ÷ (8.31 × 300) = 0.0201 mol. (b) T₂ = 300 × (2.0 × 10⁶ × 5.0 × 10⁻⁵) ÷ (1.0 × 10⁵ × 5.0 × 10⁻⁴) = 600 K. (c) At constant V, p ∝ T: p₃ = 2.0 × 10⁶ × 2400 ÷ 600 = 8.0 × 10⁶ Pa. (d) F = 8.0 × 10⁶ × 5.0 × 10⁻³ = 4.0 × 10⁴ N. Mark scheme (7 marks). C1: n = pV/RT. C1: pV/T constant. A1: T₂ = 600 K. C1: p ∝ T at constant V. C1: F = pA. A1: F = 4.0 × 10⁴ N. A1: p₃ = 8.0 × 10⁶ Pa.', 7)
