('61d43e6c-2f85-56f4-8706-7f49ed7fd734', 'ac1e8884-26be-5df8-b0e4-1499b11b872e', 'High pressure and low temperature', 'A', false, 0),
('c7df68fb-148e-5a29-b01c-98b2a6af725c', 'ac1e8884-26be-5df8-b0e4-1499b11b872e', 'High pressure and high temperature', 'B', false, 1),
