('acd51647-ffb3-5972-885e-2829705c114a', '0b0f7705-01f5-5b73-8bf8-7725d1cac903', 'It stays the same', 'A', true, 0),
('f83571f5-c587-5bab-b52c-789d21231f9f', '0b0f7705-01f5-5b73-8bf8-7725d1cac903', 'It doubles', 'B', false, 1),
