('4da7be24-ce45-5449-9798-e7b69cba86d1', 'f2957c25-afe3-5129-8132-95aa94712594', 'The molar mass of the gas', 'D', true, 3),
('5aaae5ae-916d-5b6d-8d8b-f7e059035c87', '6eded013-2d72-5e4e-b8f9-854390ad6213', 'The carbon dioxide container holds more molecules', 'A', false, 0),
('eb7d76b6-f191-5891-b468-8b5c25065e8f', '6eded013-2d72-5e4e-b8f9-854390ad6213', 'They contain the same number of molecules', 'B', true, 1),
('fff49bf2-c501-5382-a3f3-19d0327a9444', '6eded013-2d72-5e4e-b8f9-854390ad6213', 'The hydrogen container holds more molecules', 'C', false, 2),
('b22f6100-9f99-521e-ba12-a70af42b14e4', '6eded013-2d72-5e4e-b8f9-854390ad6213', 'They contain the same mass of gas', 'D', false, 3),
('f7ace77d-f6c2-5780-b201-e39669b03410', 'faeb99f1-e3db-53c8-9a3a-7a5a4c15e033', 'It is about 11 times too large', 'A', false, 0),
('ad578341-949b-5f8a-a662-8283b2961397', 'faeb99f1-e3db-53c8-9a3a-7a5a4c15e033', 'It is correct, because temperature differences are the same in °C and K', 'B', false, 1),
('5837bbf6-a278-5da9-ab8a-a19791fdb771', 'faeb99f1-e3db-53c8-9a3a-7a5a4c15e033', 'It is about 11 times too small', 'C', true, 2),
('bdd556dd-7b4b-5ce6-8bc5-aba2da7463c9', 'faeb99f1-e3db-53c8-9a3a-7a5a4c15e033', 'It is about 273 times too small', 'D', false, 3),
('481150da-7c47-5a2c-aced-f060c3f492fa', '3cd327c2-19c1-5e0f-bde8-f6dca8e8e685', 'It stays the same', 'A', true, 0),
('b1d6927e-519c-5dfa-8a5d-02dc69697463', '3cd327c2-19c1-5e0f-bde8-f6dca8e8e685', 'It doubles', 'B', false, 1),
('4381778b-90fa-522c-9ae9-9a1572cd146b', '3cd327c2-19c1-5e0f-bde8-f6dca8e8e685', 'It quadruples', 'C', false, 2),
('44c062a8-9319-5a7c-8eb0-a0c55c894bd0', '3cd327c2-19c1-5e0f-bde8-f6dca8e8e685', 'It halves', 'D', false, 3),
('6b1b1b9a-e5c9-5742-8b6a-0f9a8f52f05b', '8f30f14c-a0b0-5d63-ab13-54b52c73a724', 'Volume against Celsius temperature', 'A', false, 0),
('7c0cf2f4-eb74-54d3-bf33-f17e233472c9', '8f30f14c-a0b0-5d63-ab13-54b52c73a724', 'Volume against 1/T', 'B', false, 1),
('306fed2a-02b4-5ff9-a8d5-fc64f4776076', '8f30f14c-a0b0-5d63-ab13-54b52c73a724', 'Pressure against volume', 'C', false, 2),
('63849e1d-0797-58ec-964f-303d84d56f1b', '8f30f14c-a0b0-5d63-ab13-54b52c73a724', 'Volume against thermodynamic temperature', 'D', true, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('46412985-675d-56ef-9f4e-560cc3eb638f', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 9, 9, 'In the kinetic-theory equation pV = ⅓Nm⟨c²⟩, what does ⟨c²⟩ represent?', NULL, 1, 'multiple_choice'::answer_type, 'The mean of the squares of the molecular speeds', NULL, false, NULL, false, NULL, '⟨c²⟩ is found by squaring every speed and then averaging. Its square root is the r.m.s. speed. Mark scheme (1 mark). B1: C (The mean of the squares of the molecular speeds).', 1),
('0deaa71c-cb7e-5f29-9d6b-1c8cdc317ca0', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 10, 10, 'Why does the kinetic theory assume that a gas contains a very large number of molecules?', NULL, 1, 'multiple_choice'::answer_type, 'So that average quantities, such as the mean square speed, are well defined and steady', NULL, false, NULL, false, NULL, 'With huge numbers, random fluctuations average out and the pressure is steady. Mark scheme (1 mark). B1: A (So that average quantities, such as the mean square speed, are well defined and steady).', 1),
('6b1d5004-ad1b-5bf4-97a5-15e36af0489b', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 11, 11, 'A container of volume 0.10 m³ holds 2.0 × 10²⁴ helium atoms, each of mass 6.6 × 10⁻²⁷ kg. The mean square speed of the atoms is 1.8 × 10⁶ m² s⁻². Calculate the pressure.', NULL, 1, 'numeric'::answer_type, '79200', 'Pa', false, NULL, false, NULL, 'p = Nm⟨c²⟩/3V = 2.0 × 10²⁴ × 6.6 × 10⁻²⁷ × 1.8 × 10⁶ ÷ (3 × 0.10) = 7.92 × 10⁴ Pa. Mark scheme (2 marks). C1: p = Nm⟨c²⟩/3V. A1: p = 7.92 × 10⁴ Pa.', 2),
('62693231-e214-5d08-847e-0f7e64415a05', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 12, 12, 'Calculate the r.m.s. speed of helium atoms (mass 6.64 × 10⁻²⁷ kg) at 273 K. Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 1, 'numeric'::answer_type, '1305', 'm s⁻¹', false, NULL, false, NULL, 'c_rms = √(3kT/m) = √(3 × 1.38 × 10⁻²³ × 273 ÷ 6.64 × 10⁻²⁷) = 1300 m s⁻¹. Mark scheme (2 marks). C1: c_rms = √(3kT/m). A1: c_rms = 1300 m s⁻¹.', 2),
('eb53762c-3951-5ac1-b236-a9a55a6add4d', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 13, 13, 'The Boltzmann constant k is equal to which of the following?', NULL, 1, 'multiple_choice'::answer_type, 'R/N_A', NULL, false, NULL, false, NULL, 'k is the gas constant per molecule: k = R/N_A = 8.31 ÷ 6.02 × 10²³ = 1.38 × 10⁻²³ J K⁻¹. Mark scheme (1 mark). B1: D (R/N_A).', 1),
('62b67e0a-1c1f-5db2-bae6-f795dabcdec4', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 14, 14, 'Calculate the r.m.s. speed of oxygen molecules at 290 K. The molar mass of oxygen is 0.032 kg mol⁻¹. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '475.3', 'm s⁻¹', false, NULL, false, NULL, 'c_rms = √(3RT/M) = √(3 × 8.31 × 290 ÷ 0.032) = 475 m s⁻¹. Mark scheme (2 marks). C1: c_rms = √(3RT/M). A1: c_rms = 475 m s⁻¹.', 2),
('d69ef8cc-9005-51ee-b781-cb0eae1a2894', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 15, 15, 'The thermodynamic temperature of a gas is made four times larger. What happens to the r.m.s. speed of its molecules?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'c_rms ∝ √T, and √4 = 2. Mark scheme (1 mark). B1: B (It doubles).', 1),
('2c8fff4b-7a36-5d11-a8e3-b82970561986', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 16, 16, 'The gas leaving a furnace chimney is at 1000 K. Find the average translational kinetic energy of one of its molecules, in units of 10⁻²¹ J. Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 1, 'numeric'::answer_type, '20.7', '10⁻²¹ J', false, NULL, false, NULL, '⟨E_k⟩ = (3/2)kT = 1.5 × 1.38 × 10⁻²³ × 1000 = 2.07 × 10⁻²⁰ J. Mark scheme (2 marks). C1: ⟨E_k⟩ = (3/2)kT. A1: ⟨E_k⟩ = 20.7 × 10⁻²¹ J.', 2),
('1c4445d6-4fd2-5d69-aca2-cf2a0aecc5fe', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 17, 17, 'The result ½m⟨c²⟩ = (3/2)kT is obtained by combining pV = ⅓Nm⟨c²⟩ with which other equation?', NULL, 1, 'multiple_choice'::answer_type, 'pV = NkT', NULL, false, NULL, false, NULL, 'Equating ⅓Nm⟨c²⟩ with NkT gives m⟨c²⟩ = 3kT, so ½m⟨c²⟩ = (3/2)kT. Mark scheme (1 mark). B1: C (pV = NkT).', 1),
('58e898bc-b5ae-5bd1-8789-6d0e0a8bc0d0', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 18, 18, 'Neon atoms in a discharge tube have a mean translational kinetic energy of 6.2 × 10⁻²¹ J. Calculate the temperature of the neon. Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 1, 'numeric'::answer_type, '299.5', 'K', false, NULL, false, NULL, 'T = 2⟨E_k⟩/3k = 2 × 6.2 × 10⁻²¹ ÷ (3 × 1.38 × 10⁻²³) = 300 K. Mark scheme (2 marks). C1: rearranged (3/2)kT. A1: T = 300 K.', 2),
('53204d06-01ec-5f63-9a97-037a0e0e6ef2', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 19, 19, 'A gas is compressed slowly so that its temperature stays constant. What happens to the r.m.s. speed of its molecules?', NULL, 1, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'c_rms depends only on T and the molecular mass, not on pressure or volume. Mark scheme (1 mark). B1: A (It stays the same).', 1),
('3a4dfb9a-05cb-5ba3-aac3-9e9f496f4250', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 20, 20, 'The molecules of a gas in a 0.020 m³ container have a total translational kinetic energy of 4500 J. Calculate the pressure of the gas.', NULL, 1, 'numeric'::answer_type, '1.5e5', 'Pa', false, NULL, false, NULL, 'pV = ⅔ × total kinetic energy, so p = 2 × 4500 ÷ (3 × 0.020) = 1.5 × 10⁵ Pa. Mark scheme (2 marks). C1: pV = ⅔E_total. A1: p = 1.5 × 10⁵ Pa.', 2),
('3713b18e-7c5e-5a98-a516-b31605085f3f', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 21, 21, 'At the same temperature, why do hydrogen molecules move faster on average than oxygen molecules?', NULL, 1, 'multiple_choice'::answer_type, 'They have the same mean kinetic energy but a smaller mass', NULL, false, NULL, false, NULL, '½m⟨c²⟩ is the same for both, so the lighter molecule has the larger ⟨c²⟩. Mark scheme (1 mark). B1: D (They have the same mean kinetic energy but a smaller mass).', 1),
('134e00b8-723f-5c1d-a96c-b68e27e55bba', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 22, 22, 'Calculate the temperature at which argon atoms (molar mass 0.040 kg mol⁻¹) have an r.m.s. speed of 500 m s⁻¹. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '401.1', 'K', false, NULL, false, NULL, 'T = Mc²/3R = 0.040 × 500² ÷ (3 × 8.31) = 401 K. Mark scheme (2 marks). C1: T = M⟨c²⟩/3R. A1: T = 401 K.', 2),
('2eedb580-873e-5b30-ad3d-44cfb35d22a9', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 23, 23, 'Which describes the graph of the mean translational kinetic energy of gas molecules against thermodynamic temperature?', NULL, 1, 'multiple_choice'::answer_type, 'A straight line through the origin', NULL, false, NULL, false, NULL, '⟨E_k⟩ = (3/2)kT, so the graph is a line through the origin with gradient (3/2)k. Mark scheme (1 mark). B1: B (A straight line through the origin).', 1),
('4b1b7d5e-f3dc-52f9-ba38-01bd89328f87', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 24, 24, 'Hydrogen (molar mass 0.002 kg mol⁻¹) and oxygen (molar mass 0.032 kg mol⁻¹) are at the same temperature. Calculate the ratio of the r.m.s. speed of hydrogen molecules to that of oxygen molecules.', NULL, 1, 'numeric'::answer_type, '4', NULL, false, NULL, false, NULL, 'Ratio = √(0.032 ÷ 0.002) = 4. Mark scheme (1 mark). A1: ratio = 4.0.', 1),
('b49499fe-8799-5bde-8c79-20fd34b0cb1d', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 25, 25, 'What is the SI unit of the Boltzmann constant?', NULL, 1, 'multiple_choice'::answer_type, 'J K⁻¹', NULL, false, NULL, false, NULL, 'k = (energy per molecule) ÷ temperature, so its unit is J K⁻¹. Mark scheme (1 mark). B1: C (J K⁻¹).', 1),
('a55bd78d-7c4d-54f6-bb24-452f281bf515', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 26, 26, 'A sample of gas has 2.4 × 10²² molecules in a volume of 1.0 × 10⁻³ m³ at a pressure of 1.0 × 10⁵ Pa. Calculate the mean translational kinetic energy of a molecule, in units of 10⁻²¹ J.', NULL, 2, 'numeric'::answer_type, '6.25', '10⁻²¹ J', false, NULL, false, NULL, 'pV = ⅓Nm⟨c²⟩ = ⅔N⟨E_k⟩, so ⟨E_k⟩ = 3pV/2N = 3 × 1.0 × 10⁵ × 1.0 × 10⁻³ ÷ (2 × 2.4 × 10²²) = 6.25 × 10⁻²¹ J. Mark scheme (3 marks). M1: pV = ⅔N⟨E_k⟩. C1: substitution. A1: ⟨E_k⟩ = 6.25 × 10⁻²¹ J.', 3),
('3870e01e-e0f2-5d1c-bf4f-24831ee1e401', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 27, 27, 'The atmosphere of Mars is mostly carbon dioxide (molar mass 0.044 kg mol⁻¹) at about 210 K. Calculate the r.m.s. speed of the carbon dioxide molecules. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '344.9', 'm s⁻¹', false, NULL, false, NULL, 'c_rms = √(3RT/M) = √(3 × 8.31 × 210 ÷ 0.044) = 345 m s⁻¹. Mark scheme (3 marks). C1: c_rms = √(3RT/M). C1: substitution. A1: c_rms = 345 m s⁻¹.', 3),
('826eeea2-a780-55d4-bfc6-fc3977e82b1d', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 28, 28, 'At what temperature would nitrogen molecules (molar mass 0.028 kg mol⁻¹) have the same r.m.s. speed as hydrogen molecules (molar mass 0.002 kg mol⁻¹) at 300 K?', NULL, 2, 'numeric'::answer_type, '4200', 'K', false, NULL, false, NULL, 'c_rms² = 3RT/M, so equal speeds need T/M equal: T = 300 × 0.028 ÷ 0.002 = 4200 K. Mark scheme (4 marks). M1: c_rms² ∝ T/M. C1: T/M equal. C1: substitution. A1: T = 4200 K.', 4),
('6775962d-0fbc-5509-b22d-3e9fc257bbfb', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 29, 29, 'Gas X has molecules four times as massive as those of gas Y. The gases are at the same temperature. What is (r.m.s. speed of X) ÷ (r.m.s. speed of Y)?', NULL, 2, 'multiple_choice'::answer_type, '1/2', NULL, false, NULL, false, NULL, 'Equal mean kinetic energies mean c_rms ∝ 1/√m, so the ratio is 1/√4 = 1/2. 1/4 forgets the square root. Mark scheme (3 marks). C1: same ⟨E_k⟩. C1: c_rms ∝ 1/√m. A1: A (1/2).', 3),
('d6da50ad-bbec-5946-a863-a4bc596ef635', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 30, 30, 'Uranium can be enriched using gaseous uranium hexafluoride. Molecules containing uranium-235 have molar mass 0.349 kg mol⁻¹ and those containing uranium-238 have molar mass 0.352 kg mol⁻¹. At the same temperature, calculate the percentage by which the r.m.s. speed of the lighter molecules exceeds that of the heavier molecules.', NULL, 2, 'numeric'::answer_type, '0.4289', '%', false, NULL, false, NULL, 'c_rms ∝ 1/√M, so the speed ratio = √(0.352 ÷ 0.349) = 1.00429. Percentage = (1.00429 − 1) × 100 = 0.429 %. Mark scheme (3 marks). C1: c_rms ∝ 1/√M. C1: speed ratio. A1: percentage = 0.429%.', 3),
('db7155e9-12ca-5577-bef3-afb823676ead', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 31, 31, 'Oxygen molecules, each of mass 5.3 × 10⁻²⁶ kg, have an r.m.s. speed of 480 m s⁻¹. Calculate the temperature of the oxygen. Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 2, 'numeric'::answer_type, '295', 'K', false, NULL, false, NULL, '½m⟨c²⟩ = (3/2)kT, so T = m⟨c²⟩/3k = 5.3 × 10⁻²⁶ × 480² ÷ (3 × 1.38 × 10⁻²³) = 295 K. Mark scheme (4 marks). M1: ½m⟨c²⟩ = (3/2)kT. C1: ⟨c²⟩ = 480². C1: substitution. A1: T = 295 K.', 4),
('7389d7b2-26d0-5ad5-8527-e20eaeb57653', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 32, 32, 'Which change would double the r.m.s. speed of the molecules of a fixed sample of gas?', NULL, 2, 'multiple_choice'::answer_type, 'Increasing its thermodynamic temperature by a factor of 4', NULL, false, NULL, false, NULL, 'c_rms ∝ √T. Changing p or V at constant T leaves c_rms unchanged. Mark scheme (3 marks). C1: c_rms ∝ √T. C1: factor 4 in T. A1: D (Increasing its thermodynamic temperature by a factor of 4).', 3),
('ef6a45fb-cc55-520c-8a0a-d6da6f086ce5', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 33, 33, 'Hydrogen atoms (mass 1.67 × 10⁻²⁷ kg) in the upper atmosphere are at about 1000 K. Calculate their r.m.s. speed, in km s⁻¹. Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 2, 'numeric'::answer_type, '4.979', 'km s⁻¹', false, NULL, false, NULL, 'c_rms = √(3kT/m) = √(3 × 1.38 × 10⁻²³ × 1000 ÷ 1.67 × 10⁻²⁷) = 4980 m s⁻¹. In km s⁻¹: 4979 ÷ 1000 = 4.98. Mark scheme (3 marks). C1: c_rms = √(3kT/m). C1: unit conversion. A1: c_rms = 4.98 km s⁻¹.', 3),
('db52c82f-9e10-5df3-b4cc-f7fba388832b', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 34, 34, 'A balloon of volume 2.0 litres contains air at 1.1 × 10⁵ Pa. Use pV = ⅓Nm⟨c²⟩ to calculate the total translational kinetic energy of the air molecules.', NULL, 2, 'numeric'::answer_type, '330', 'J', false, NULL, false, NULL, 'Total E_k = ½Nm⟨c²⟩ = (3/2)pV = 1.5 × 1.1 × 10⁵ × 2.0 × 10⁻³ = 330 J. Mark scheme (3 marks). M1: E_total = (3/2)pV. C1: V in m³. A1: E = 330 J.', 3),
('2216045d-0e00-5551-b2ac-d5820d9b61d3', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 35, 35, 'In deriving pV = ⅓Nm⟨c²⟩, the mean square of the velocity component towards one wall, ⟨u²⟩, is replaced by ⅓⟨c²⟩. Which assumption justifies this?', NULL, 2, 'multiple_choice'::answer_type, 'The molecules move randomly, with no preferred direction', NULL, false, NULL, false, NULL, 'c² = u² + v² + w², and random motion makes the three averages equal, so ⟨u²⟩ = ⅓⟨c²⟩. Mark scheme (4 marks). C1: c² = u² + v² + w². C1: random motion so components equal. C1: hence ⅓. A1: B (The molecules move randomly, with no preferred direction).', 4),
('8d4bca85-5122-5f54-89af-7e8194181917', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 36, 36, 'Calculate the ratio of the mean translational kinetic energy of the molecules of a gas at 100 °C to that at 0 °C.', NULL, 2, 'numeric'::answer_type, '1.366', NULL, false, NULL, false, NULL, '⟨E_k⟩ ∝ T, so ratio = 373 ÷ 273 = 1.37. Mark scheme (3 marks). C1: ⟨E_k⟩ ∝ T. C1: temperatures in kelvin. A1: ratio = 1.37.', 3),
('315168b5-f331-53f3-88d0-ad3fd7b6e9e8', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 37, 37, 'At 273 K and 1.0 × 10⁵ Pa the molecules of a gas have an r.m.s. speed of 1840 m s⁻¹. Calculate the molar mass of the gas and identify it. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '0.00201', 'kg mol⁻¹', false, NULL, false, NULL, 'c_rms² = 3RT/M, so M = 3RT/c² = 3 × 8.31 × 273 ÷ 1840² = 0.00201 kg mol⁻¹: hydrogen, H₂. Mark scheme (4 marks). M1: M = 3RT/⟨c²⟩. C1: substitution. B1: identifies hydrogen. A1: M = 0.00201 kg mol⁻¹.', 4),
('7683945f-7308-56b0-9a58-1ab24a5684b7', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 38, 38, 'Why is the r.m.s. speed, rather than the mean velocity, used to describe molecular motion in a gas?', NULL, 2, 'multiple_choice'::answer_type, 'The mean velocity is zero, because the molecules move randomly in all directions', NULL, false, NULL, false, NULL, 'Velocities in opposite directions cancel, so the mean velocity of a still gas is zero; squaring removes the direction. Mark scheme (3 marks). C1: random directions. C1: velocities cancel. A1: C (The mean velocity is zero, because the molecules move randomly in all directions).', 3),
('276d110c-8e6a-52f4-afa2-ca97664ba21f', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 39, 39, 'The molecules of a gas have an r.m.s. speed of 400 m s⁻¹ at 27 °C. Calculate their r.m.s. speed at 327 °C.', NULL, 2, 'numeric'::answer_type, '565.7', 'm s⁻¹', false, NULL, false, NULL, 'c_rms ∝ √T: c₂ = 400 × √(600 ÷ 300) = 566 m s⁻¹. Mark scheme (3 marks). C1: temperatures 300 K and 600 K. C1: c ∝ √T. A1: c_rms = 566 m s⁻¹.', 3),
('f5fc0b52-b079-54dd-8570-1c80c0bf1ea5', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 40, 40, 'The molecules of a gas at 400 K have a total translational kinetic energy of 3.0 kJ. Calculate the number of molecules. Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 2, 'numeric'::answer_type, '3.623e23', NULL, false, NULL, false, NULL, 'N = E_total ÷ (3/2)kT = 3000 ÷ (1.5 × 1.38 × 10⁻²³ × 400) = 3.62 × 10²³. Mark scheme (3 marks). C1: ⟨E_k⟩ = (3/2)kT. C1: N = E_total/⟨E_k⟩. A1: N = 3.62 × 10²³.', 3),
('4c85dbd8-96b4-5c6e-9ecd-cae1480f51ce', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 41, 41, 'The number of molecules in a rigid container is doubled while the temperature is kept constant. Which row is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Pressure doubles; r.m.s. speed is unchanged', NULL, false, NULL, false, NULL, 'p = NkT/V doubles with N, but c_rms depends only on T and m. Mark scheme (3 marks). C1: p ∝ N. C1: c_rms depends on T only. A1: A (Pressure doubles; r.m.s. speed is unchanged).', 3),
('7885f41f-de05-550f-afad-8ca61cf8ca7f', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 42, 42, '(a) Starting from pV = ⅓Nm⟨c²⟩ and pV = NkT, show that the mean translational kinetic energy of a molecule is (3/2)kT. (b) A xenon atom has mass 2.18 × 10⁻²⁵ kg. Calculate the r.m.s. speed of xenon atoms at 300 K. (c) Calculate the mean translational kinetic energy of a xenon atom at 300 K, in units of 10⁻²¹ J. Give only the answer to (b). Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 3, 'numeric'::answer_type, '238.7', 'm s⁻¹', false, NULL, false, NULL, '(a) ⅓Nm⟨c²⟩ = NkT gives m⟨c²⟩ = 3kT, so ½m⟨c²⟩ = (3/2)kT. (b) c_rms = √(3 × 1.38 × 10⁻²³ × 300 ÷ 2.18 × 10⁻²⁵) = 239 m s⁻¹. (c) ⟨E_k⟩ = 1.5 × 1.38 × 10⁻²³ × 300 = 6.21 × 10⁻²¹ J, which is 6.21 in units of 10⁻²¹ J. Mark scheme (6 marks). M1: equates the two expressions. A1: ½m⟨c²⟩ = (3/2)kT shown. C1: c_rms = √(3kT/m). C1: substitution. C1: (3/2)kT value. A1: c_rms = 239 m s⁻¹.', 6),
('91184694-41df-52c8-aae1-4c51bb70c399', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 43, 43, 'A container holds a mixture of hydrogen molecules (mass 3.34 × 10⁻²⁷ kg) and oxygen molecules (mass 5.31 × 10⁻²⁶ kg) at 300 K. (a) Calculate the mean translational kinetic energy of each kind of molecule, in units of 10⁻²¹ J. (b) Calculate the r.m.s. speed of the hydrogen molecules. (c) Calculate the ratio (r.m.s. speed of hydrogen) ÷ (r.m.s. speed of oxygen). Give only the answer to (c). Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 3, 'numeric'::answer_type, '3.987', NULL, false, NULL, false, NULL, '(a) Both have ⟨E_k⟩ = 1.5 × 1.38 × 10⁻²³ × 300 = 6.21 × 10⁻²¹ J. (b) c_rms = √(3 × 1.38 × 10⁻²³ × 300 ÷ 3.34 × 10⁻²⁷) = 1930 m s⁻¹. (c) Equal ⟨E_k⟩, so ratio = √(5.31 × 10⁻²⁶ ÷ 3.34 × 10⁻²⁷) = 3.99. Mark scheme (5 marks). C1: same ⟨E_k⟩ for both. C1: c_rms for hydrogen. M1: c ∝ 1/√m. C1: substitution. A1: ratio = 3.99.', 5),
('c44b2915-203b-5082-aa5e-0d283865f15a', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 44, 44, 'The escape speed from the Moon is 2.4 km s⁻¹ and its daytime surface temperature is about 390 K. (a) Calculate the r.m.s. speed of nitrogen molecules (mass 4.65 × 10⁻²⁶ kg) at 390 K. (b) Calculate the r.m.s. speed of helium atoms (mass 6.64 × 10⁻²⁷ kg) at 390 K. (c) Both r.m.s. speeds are less than the escape speed. Explain why the Moon has still lost these gases. Give only the answer to (b). Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 3, 'numeric'::answer_type, '1559', 'm s⁻¹', false, NULL, false, NULL, '(a) c_rms = √(3 × 1.38 × 10⁻²³ × 390 ÷ 4.65 × 10⁻²⁶) = 589 m s⁻¹. (b) c_rms = √(3 × 1.38 × 10⁻²³ × 390 ÷ 6.64 × 10⁻²⁷) = 1560 m s⁻¹. (c) The molecules have a wide range of speeds. A fraction move faster than 2.4 km s⁻¹; they escape, collisions give other molecules high speeds, and over millions of years the gas is lost. Mark scheme (6 marks). C1: c_rms = √(3kT/m). A1: nitrogen value. C1: helium substitution. B1: distribution of speeds. B1: continual loss over long times. A1: c_rms = 1560 m s⁻¹.', 6),
('d9221636-987f-54c9-a3c4-8e26c81c0b55', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 45, 45, 'A container of volume 0.024 m³ holds 1.0 mol of argon (molar mass 0.040 kg mol⁻¹) at 290 K. (a) Calculate the pressure. (b) Calculate the density of the argon. (c) Use p = ⅓ρ⟨c²⟩ to calculate the r.m.s. speed of the atoms. Give only the answer to (c). Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '425.1', 'm s⁻¹', false, NULL, false, NULL, '(a) p = 1.0 × 8.31 × 290 ÷ 0.024 = 1.00 × 10⁵ Pa. (b) ρ = 0.040 ÷ 0.024 = 1.67 kg m⁻³. (c) c_rms = √(3p/ρ) = √(3 × 1.004 × 10⁵ ÷ 1.667) = 425 m s⁻¹. Mark scheme (5 marks). C1: p = nRT/V. C1: ρ = m/V. C1: ⟨c²⟩ = 3p/ρ. C1: square root. A1: c_rms = 425 m s⁻¹.', 5),
('fd055111-5d47-57c5-bb8c-10698f271a67', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 46, 46, 'A computer model gives the r.m.s. speed of nitrogen molecules at different temperatures: T/K = 200, 300, 400, 500 and c_rms/m s⁻¹ = 422, 517, 597, 667. (a) Show that c_rms² is proportional to T. (b) Use the reading at 500 K to calculate the mass of a nitrogen molecule, in units of 10⁻²⁶ kg. (c) Use your answer to (b) to calculate the molar mass of nitrogen. Give only the answer to (b). Take k = 1.38 × 10⁻²³ J K⁻¹ and N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '4.653', '10⁻²⁶ kg', false, NULL, false, NULL, '(a) c²/T = 422² ÷ 200 = 890 m² s⁻² K⁻¹; the other readings also give about 890, so c² ∝ T. (b) m = 3kT/c² = 3 × 1.38 × 10⁻²³ × 500 ÷ 667² = 4.65 × 10⁻²⁶ kg. (c) M = mN_A = 4.653 × 10⁻²⁶ × 6.02 × 10²³ = 0.0280 kg mol⁻¹. Mark scheme (6 marks). C1: c²/T calculated. B1: constant, so proportional. M1: m = 3kT/⟨c²⟩. C1: substitution. C1: M = mN_A. A1: m = 4.65 × 10⁻²⁶ kg.', 6),
('147ebe14-0a2e-5947-99ad-3d969d808569', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 47, 47, 'A sealed 2.0 litre flask contains helium at 1.5 × 10⁵ Pa and 300 K. (a) Calculate the total translational kinetic energy of the helium atoms. (b) Calculate the number of helium atoms. (c) Use (a) and (b) to find the mean kinetic energy per atom and show that it agrees with (3/2)kT. Give only the answer to (b). Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 3, 'numeric'::answer_type, '7.246e22', NULL, false, NULL, false, NULL, '(a) E_total = (3/2)pV = 1.5 × 1.5 × 10⁵ × 2.0 × 10⁻³ = 450 J. (b) N = pV/kT = 1.5 × 10⁵ × 2.0 × 10⁻³ ÷ (1.38 × 10⁻²³ × 300) = 7.25 × 10²². (c) ⟨E_k⟩ = 450 ÷ 7.246 × 10²² = 6.21 × 10⁻²¹ J, and (3/2)kT = 1.5 × 1.38 × 10⁻²³ × 300 = 6.21 × 10⁻²¹ J, the same. Mark scheme (5 marks). C1: E_total = (3/2)pV. C1: N = pV/kT. C1: mean = E_total/N. B1: agrees with (3/2)kT. A1: N = 7.25 × 10²².', 5),
('d195755e-6bae-523d-8735-dc637aedb175', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 48, 48, 'A cylinder of volume 0.050 m³ contains 2.0 mol of nitrogen at 300 K. It is left in sunlight and warms to 330 K. (a) Calculate the initial pressure. (b) Calculate the percentage increase in the r.m.s. speed of the molecules. (c) Calculate the percentage increase in the pressure. (d) Explain, in terms of the molecules, why the pressure rises by a larger percentage than the r.m.s. speed. Give only the answer to (b), in %. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '4.881', '%', false, NULL, false, NULL, '(a) p = 2.0 × 8.31 × 300 ÷ 0.050 = 9.97 × 10⁴ Pa. (b) c ∝ √T: √(330 ÷ 300) = 1.0488, so the increase = (1.0488 − 1) × 100 = 4.88 %. (c) p ∝ T, so the pressure rises by 10 %. (d) Faster molecules give a larger momentum change per collision and also collide more often; both factors scale with speed, so p ∝ c². Mark scheme (6 marks). C1: p = nRT/V. C1: c ∝ √T. C1: percentage. B1: pressure up 10 %. B1: two effects of speed on pressure. A1: increase = 4.88%.', 6),
('dfbe56d5-f1fc-5c15-8cda-fc028ce14078', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 49, 49, '(a) Show that the r.m.s. speed of air molecules (mean molar mass 0.029 kg mol⁻¹) at 300 K is about 500 m s⁻¹. (b) The speed of sound in air at 300 K is about 350 m s⁻¹. Suggest why it is of the same order as the r.m.s. speed. (c) Calculate the temperature at which the r.m.s. speed of air molecules would be 1000 m s⁻¹. Give only the answer to (c). Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '1163', 'K', false, NULL, false, NULL, '(a) c_rms = √(3 × 8.31 × 300 ÷ 0.029) = 508 m s⁻¹ ≈ 500 m s⁻¹. (b) Sound is passed on by molecular collisions, so it cannot travel much faster than the molecules themselves. (c) T ∝ c²: T = 300 × (1000 ÷ 507.8)² = 1160 K. Mark scheme (5 marks). C1: c_rms = √(3RT/M). B1: about 500 m s⁻¹ shown. B1: sound carried by molecular motion. M1: T ∝ c². A1: T = 1160 K.', 5),
('edf30cce-f8ec-5050-b838-abf46bb0d435', '468b27d0-3cef-43ee-aeef-09b1a340050f', '50c14949-b5ee-5ec0-85da-611fddf81a19', 'a-level', '20.7', '9702 coursebook 20.7 · Kinetic theory of gases', 50, 50, 'A fixed mass of gas is heated at constant volume from 250 K to 400 K. (a) Calculate the factor by which the r.m.s. speed of the molecules increases. (b) State the factor by which the momentum change per collision with a wall increases. (c) State the factor by which the number of collisions per second with a wall increases. (d) Hence show that the pressure increases by a factor of 1.6. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '1.265', NULL, false, NULL, false, NULL, '(a) c ∝ √T: factor = √(400 ÷ 250) = 1.26. (b) Δp = 2mc, so it increases by the same factor, 1.26. (c) The time between collisions is proportional to 1/c, so the rate also increases by 1.26. (d) Pressure factor = 1.265 × 1.265 = 1.6, which equals 400 ÷ 250. Mark scheme (5 marks). C1: c ∝ √T. B1: Δp ∝ c. B1: rate ∝ c. B1: product = 1.6 = T₂/T₁. A1: factor = 1.26.', 5)
